+
+export interface ToolContent {
+  type: 'text';
+  text: string;
+}
+
+export interface ToolResult {
+  content: ToolContent[];
+  isError?: boolean;
+}
+
+export interface JSONSchema {
+  type: string;
+  properties?: Record<string, JSONSchema & { description?: string }>;
+  required?: string[];
+  [key: string]: unknown;
+}
+
+export interface ToolAnnotations {
+  readOnlyHint?: boolean;
+  destructiveHint?: boolean;
+  idempotentHint?: boolean;
+  openWorldHint?: boolean;
+}
+
+export interface ModelContextTool<TInput = Record<string, unknown>> {
+  name: string;
+  description: string;
+  inputSchema: JSONSchema;
+  annotations?: ToolAnnotations;
+  execute: (input: TInput, client?: unknown) => Promise<ToolResult> | ToolResult;
+}
+
+interface ModelContext {
+  registerTool: (
+    tool: ModelContextTool<any>,
+    options?: { signal?: AbortSignal },
+  ) => { unregister?: () => void } | void;
+  unregisterTool?: (name: string) => void;
+}
+
+declare global {
+  interface Navigator {
+    modelContext?: ModelContext;
+  }
+}
+
+export const textResult = (text: string, isError = false): ToolResult => ({
+  content: [{ type: 'text', text }],
+  ...(isError ? { isError: true } : {}),
+});
+
+/**
+ * Registers a tool with the browser's model context. Returns a cleanup
+ * function that unregisters it again. Supports both the AbortSignal-based and
+ * the older `unregisterTool(name)` / returned-handle variants of the API.
+ */
+export function registerTool<TInput>(tool: ModelContextTool<TInput>): () => void {
+  if (typeof navigator === 'undefined') return () => {};
+  const modelContext = navigator.modelContext;
+  if (!modelContext || typeof modelContext.registerTool !== 'function') return () => {};
+
+  const controller = new AbortController();
+  let handle: { unregister?: () => void } | void;
+  try {
+    handle = modelContext.registerTool(tool, { signal: controller.signal });
+  } catch (err) {
+    console.warn(`[webmcp] Failed to register tool "${tool.name}":`, err);
+    return () => {};
+  }
+
+  return () => {
+    controller.abort();
+    try {
+      if (handle && typeof handle.unregister === 'function') {
+        handle.unregister();
+      } else if (typeof modelContext.unregisterTool === 'function') {
+        modelContext.unregisterTool(tool.name);
+      }
+    } catch {
+      // Already unregistered (e.g. via the abort signal) – nothing to do.
+    }
+  };
+}
+
+/**
+ * React hook that registers a WebMCP tool for the lifetime of the component.
+ * The latest `execute` callback is always used, so it may close over state
+ * without causing the tool to be re-registered on every render.
+ */
+export function useWebMCPTool<TInput>(tool: ModelContextTool<TInput>): void {
+  const executeRef = useRef(tool.execute);
+  executeRef.current = tool.execute;
+
+  const { name, description } = tool;
+  const schemaKey = JSON.stringify(tool.inputSchema);
+  const annotationsKey = JSON.stringify(tool.annotations ?? {});
+
+  useEffect(() => {
+    return registerTool<TInput>({
+      name,
+      description,
+      inputSchema: JSON.parse(schemaKey),
+      annotations: JSON.parse(annotationsKey),
+      execute: (input, client) => executeRef.current(input, client),
+    });
+  }, [name, description, schemaKey, annotationsKey]);
+}

