+    if (window.requestIdleCallback) {
+      idleHandle = window.requestIdleCallback(function () {
+        idleHandle = null;
+        flush(false);
+      }, { timeout: 2000 });
+    } else {
+      idleHandle = setTimeout(function () {
+        idleHandle = null;
+        flush(false);
+      }, 0);
