+    (function () {
+      var STORAGE_KEY = 'dailyGrindOrder';
+      var countEl = document.querySelector('.order-count');
+
+      function loadOrder() {
+        try {
+          var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
+          return Array.isArray(data) ? data : [];
+        } catch (e) {
+          return [];
+        }
+      }
+
+      function saveOrder(order) {
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify(order));
+        } catch (e) { /* storage unavailable: order lives for this page only */ }
+      }
+
+      function renderCount(order) {
+        var total = order.reduce(function (n, item) { return n + item.qty; }, 0);
+        countEl.dataset.count = total;
+        countEl.textContent = total ? total : '';
+        countEl.setAttribute('aria-label', total + (total === 1 ? ' item' : ' items') + ' in order');
+      }
+
+      function money(n) {
+        return '$' + Number(n).toFixed(2);
+      }
+
+      var order = loadOrder();
+      renderCount(order);
+
+      document.querySelectorAll('.drink-card').forEach(function (card) {
+        var form = card.querySelector('.drink-form');
+        var priceEl = card.querySelector('.drink-price');
+        var btn = card.querySelector('.add-btn');
+        var btnLabel = btn.querySelector('.add-btn-label');
+        var btnPrice = btn.querySelector('.add-btn-price');
+        var status = card.querySelector('.drink-status');
+        var img = card.querySelector('.drink-media img');
+        var resetTimer;
+
+        // Give each card's radio group a unique name so groups stay independent.
+        form.querySelectorAll('input[name="size"]').forEach(function (input) {
+          input.name = card.dataset.id + '-size';
+        });
+
+        function selected() {
+          return form.querySelector('input[type="radio"]:checked');
+        }
+
+        function updatePrice() {
+          var input = selected();
+          if (!input) return;
+          priceEl.textContent = money(input.dataset.price);
+          btnPrice.textContent = money(input.dataset.price);
+        }
+
+        if (img) {
+          img.addEventListener('error', function () { img.classList.add('is-broken'); });
+          if (img.complete && img.naturalWidth === 0) img.classList.add('is-broken');
+        }
+
+        form.addEventListener('change', updatePrice);
+
+        form.addEventListener('submit', function (e) {
+          e.preventDefault();
+          var input = selected();
+          if (!input) return;
+
+          var size = input.value;
+          var price = parseFloat(input.dataset.price);
+          var existing = order.find(function (item) {
+            return item.id === card.dataset.id && item.size === size;
+          });
+          if (existing) {
+            existing.qty += 1;
+          } else {
+            order.push({ id: card.dataset.id, name: card.dataset.name, size: size, price: price, qty: 1 });
