+// Delivery-notes sealing: hybrid / post-quantum public-key encryption in the browser.
+//
+// Construction (an HPKE-style "KEM + KDF + AEAD" envelope):
+//   1. KEM  - establish a fresh 32-byte shared secret with the store's public key using one of:
+//               * XWING  : X-Wing hybrid KEM = ML-KEM-768 + X25519 (default; secure if EITHER holds)
+//               * MLKEM768: ML-KEM-768 (FIPS 203) alone, post-quantum only
+//               * X25519 : ephemeral-static X25519 key agreement, classical only (legacy)
+//   2. KDF  - HKDF-SHA-256 over the shared secret, bound to the suite, the recipient key and the
+//             encapsulation, producing a non-extractable AES-256-GCM key (one key per message).
+//   3. AEAD - AES-256-GCM with a random 96-bit IV. Every header field (version, suite, key id,
+//             encapsulation, order reference) is authenticated as Additional Authenticated Data,
+//             so tampering with or swapping any of them makes decryption fail.
+//
+// Plaintext is padded to a bucket size before encryption so ciphertext length does not reveal
+// the exact note length. Plaintext and secret material never leave the browser.
+
+import { ml_kem768, xwing, x25519 } from '../vendor/noble-pq.js';
+
+export const ENVELOPE_VERSION = 1;
+const PROTOCOL_LABEL = 'DailyGrind/DeliveryNotes/v1';
+const PAD_BUCKET = 256;
+export const MAX_NOTE_BYTES = 2048;
+
+const enc = new TextEncoder();
+const dec = new TextDecoder('utf-8', { fatal: true });
+
+// ---------- suites ----------------------------------------------------------------------------
+
+export const SUITES = Object.freeze({
+  XWING: {
+    id: 'XWING',
+    label: 'Hybrid: X-Wing (ML-KEM-768 + X25519)',
+    pq: true,
+    classical: true,
+    keygen: () => xwing.keygen(),
+    encap: (pk) => {
+      const { cipherText, sharedSecret } = xwing.encapsulate(pk);
+      return { encapsulation: cipherText, sharedSecret };
+    },
+    decap: (encapsulation, sk) => xwing.decapsulate(encapsulation, sk),
+    lengths: { publicKey: 1216, encapsulation: 1120 },
+  },
+  MLKEM768: {
+    id: 'MLKEM768',
+    label: 'Post-quantum: ML-KEM-768 (FIPS 203)',
+    pq: true,
+    classical: false,
+    keygen: () => ml_kem768.keygen(),
+    encap: (pk) => {
+      const { cipherText, sharedSecret } = ml_kem768.encapsulate(pk);
+      return { encapsulation: cipherText, sharedSecret };
+    },
+    decap: (encapsulation, sk) => ml_kem768.decapsulate(encapsulation, sk),
+    lengths: { publicKey: 1184, encapsulation: 1088 },
+  },
+  X25519: {
+    id: 'X25519',
+    label: 'Classical: X25519 key agreement',
+    pq: false,
+    classical: true,
+    keygen: () => x25519.keygen(),
+    // Ephemeral-static Diffie-Hellman expressed as a KEM: the "encapsulation" is the ephemeral
+    // public key. The recipient public key is bound into the KDF below.
+    encap: (pk) => {
+      const eph = x25519.keygen();
+      try {
+        const sharedSecret = checkedX25519(eph.secretKey, pk);
+        return { encapsulation: eph.publicKey, sharedSecret };
+      } finally {
+        eph.secretKey.fill(0);
+      }
+    },
+    decap: (encapsulation, sk) => checkedX25519(sk, encapsulation),
+    lengths: { publicKey: 32, encapsulation: 32 },
+  },
+});
+
+export const DEFAULT_SUITE = 'XWING';
+
+function checkedX25519(sk, pk) {
+  const ss = x25519.getSharedSecret(sk, pk);
+  // Reject low-order points (all-zero output) - RFC 7748 section 6.1.
+  if (ss.every((b) => b === 0)) throw new Error('Invalid X25519 public key');
+  return ss;
+}
+
+function getSuite(id) {
+  const suite = Object.hasOwn(SUITES, id) ? SUITES[id] : undefined;
+  if (!suite) throw new Error(`Unsupported suite: ${String(id)}`);
+  return suite;
+}
+
+// ---------- encoding helpers ------------------------------------------------------------------
+
+export function b64uEncode(bytes) {
+  let s = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64uDecode(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) throw new Error('Invalid base64url');
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+function concat(...parts) {
+  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
+  let o = 0;
+  for (const p of parts) {
+    out.set(p, o);
+    o += p.length;
+  }
+  return out;
+}
+
+// Length-prefixed encoding so field boundaries are unambiguous.
+function lp(...fields) {
+  return concat(
+    ...fields.flatMap((f) => {
+      const b = typeof f === 'string' ? enc.encode(f) : f;
+      const len = new Uint8Array(4);
+      new DataView(len.buffer).setUint32(0, b.length);
+      return [len, b];
+    })
+  );
+}
+
+function requireWebCrypto() {
+  if (!globalThis.isSecureContext || !globalThis.crypto?.subtle) {
+    throw new Error('Encrypted notes require a secure (HTTPS) context with Web Crypto support.');
+  }
+  return crypto.subtle;
+}
+
+async function sha256(bytes) {
+  return new Uint8Array(await requireWebCrypto().digest('SHA-256', bytes));
+}
+
+/** Key identifier: base64url of the first 16 bytes of SHA-256(suite || publicKey). */
+export async function keyId(suiteId, publicKey) {
+  return b64uEncode((await sha256(lp(suiteId, publicKey))).subarray(0, 16));
+}
+
+/** Human-comparable fingerprint (hex groups) of a public key, for out-of-band verification. */
+export async function fingerprint(suiteId, publicKey) {
+  const h = await sha256(lp(suiteId, publicKey));
+  return Array.from(h.subarray(0, 16), (b) => b.toString(16).padStart(2, '0'))
+    .join('')
+    .match(/.{4}/g)
+    .join(' ');
+}
+
+// ---------- padding ---------------------------------------------------------------------------
+
+function pad(msg) {
+  // Format: u16 length || message || zero padding up to a multiple of PAD_BUCKET.
+  const total = Math.ceil((msg.length + 2) / PAD_BUCKET) * PAD_BUCKET;
+  const out = new Uint8Array(total);
+  new DataView(out.buffer).setUint16(0, msg.length);
+  out.set(msg, 2);
+  return out;
+}
+
+function unpad(buf) {
+  if (buf.length < 2 || buf.length % PAD_BUCKET !== 0) throw new Error('Malformed padding');
+  const len = new DataView(buf.buffer, buf.byteOffset).getUint16(0);
+  if (len > buf.length - 2) throw new Error('Malformed padding');
+  return buf.subarray(2, 2 + len);
+}
+
+// ---------- key schedule ----------------------------------------------------------------------
+
+async function deriveAeadKey(suiteId, recipientPk, encapsulation, sharedSecret, usage) {
+  const subtle = requireWebCrypto();
+  const ikm = await subtle.importKey('raw', sharedSecret, 'HKDF', false, ['deriveKey']);
+  const info = lp(PROTOCOL_LABEL, 'aead-key', suiteId, await sha256(recipientPk), await sha256(encapsulation));
+  return subtle.deriveKey(
+    { name: 'HKDF', hash: 'SHA-256', salt: enc.encode(PROTOCOL_LABEL), info },
+    ikm,
+    { name: 'AES-GCM', length: 256 },
+    false,
+    [usage]
+  );
+}
+
+function buildAad(header) {
+  return lp(PROTOCOL_LABEL, String(header.v), header.suite, header.kid, header.enc, header.ref);
+}
+
+// ---------- recipient keys --------------------------------------------------------------------
+
+/**
+ * Generate a recipient (store) key pair for a suite. In production the store's private key lives
+ * only on the fulfilment device; this is used for the in-browser demo and for tests.
+ */
+export async function generateRecipientKeyPair(suiteId) {
+  const suite = getSuite(suiteId);
+  const { publicKey, secretKey } = suite.keygen();
+  return { suite: suite.id, publicKey, secretKey, kid: await keyId(suite.id, publicKey) };
+}
+
+/** Validate and decode a published public key entry: { suite, publicKey (base64url), kid? }. */
+export async function importRecipientPublicKey(entry) {
+  const suite = getSuite(entry?.suite);
+  const publicKey = b64uDecode(entry.publicKey);
+  if (publicKey.length !== suite.lengths.publicKey) throw new Error(`Bad ${suite.id} public key length`);
+  const kid = await keyId(suite.id, publicKey);
+  if (entry.kid && entry.kid !== kid) throw new Error(`Key id mismatch for ${suite.id} key`);
+  return { suite: suite.id, publicKey, kid };
+}
+
+// ---------- seal / open -----------------------------------------------------------------------
+
+/**
+ * Encrypt a note to a recipient public key.
+ * @param {string} note       plaintext note (UTF-8)
+ * @param {{suite:string, publicKey:Uint8Array, kid:string}} recipient
+ * @param {string} ref        order / context reference, authenticated but not encrypted
+ * @returns {Promise<object>} JSON-serialisable envelope
+ */
+export async function sealNote(note, recipient, ref = '') {
+  const subtle = requireWebCrypto();
+  const suite = getSuite(recipient.suite);
+  const msg = enc.encode(note);
+  if (msg.length === 0) throw new Error('Note is empty');
+  if (msg.length > MAX_NOTE_BYTES) throw new Error(`Note exceeds ${MAX_NOTE_BYTES} bytes`);
+
+  const { encapsulation, sharedSecret } = suite.encap(recipient.publicKey);
+  let padded;
+  try {
+    const key = await deriveAeadKey(suite.id, recipient.publicKey, encapsulation, sharedSecret, 'encrypt');
+    const iv = crypto.getRandomValues(new Uint8Array(12));
+    const header = { v: ENVELOPE_VERSION, suite: suite.id, kid: recipient.kid, enc: b64uEncode(encapsulation), ref: String(ref) };
+    padded = pad(msg);
+    const ct = await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: buildAad(header), tagLength: 128 }, key, padded);
+    return { ...header, iv: b64uEncode(iv), ct: b64uEncode(new Uint8Array(ct)) };
+  } finally {
+    sharedSecret.fill(0);
+    msg.fill(0);
+    padded?.fill(0);
+  }
+}
+
+/**
+ * Decrypt an envelope with the recipient key pair. Throws on any tampering or key mismatch.
+ * @param {object} envelope
+ * @param {{suite:string, publicKey:Uint8Array, secretKey:Uint8Array, kid:string}} recipient
+ */
+export async function openNote(envelope, recipient) {
+  const subtle = requireWebCrypto();
+  if (!envelope || envelope.v !== ENVELOPE_VERSION) throw new Error('Unsupported envelope version');
+  const suite = getSuite(envelope.suite);
+  // Pin the suite to the key: an attacker cannot downgrade a hybrid key to a weaker suite.
+  if (suite.id !== recipient.suite) throw new Error('Envelope suite does not match recipient key');
+  if (envelope.kid !== recipient.kid) throw new Error('Envelope was sealed to a different key');
+
+  const encapsulation = b64uDecode(envelope.enc);
+  const iv = b64uDecode(envelope.iv);
+  const ct = b64uDecode(envelope.ct);
+  if (encapsulation.length !== suite.lengths.encapsulation) throw new Error('Bad encapsulation length');
+  if (iv.length !== 12) throw new Error('Bad IV length');
+
+  const sharedSecret = suite.decap(encapsulation, recipient.secretKey);
+  try {
+    const key = await deriveAeadKey(suite.id, recipient.publicKey, encapsulation, sharedSecret, 'decrypt');
+    const header = { v: envelope.v, suite: suite.id, kid: envelope.kid, enc: envelope.enc, ref: String(envelope.ref ?? '') };
+    let pt;
+    try {
+      pt = new Uint8Array(await subtle.decrypt({ name: 'AES-GCM', iv, additionalData: buildAad(header), tagLength: 128 }, key, ct));
+    } catch {
+      throw new Error('Authentication failed: the note was tampered with or sealed to another key');
+    }
+    try {
+      return dec.decode(unpad(pt));
+    } finally {
+      pt.fill(0);
+    }
+  } finally {
+    sharedSecret.fill(0);
+  }
+}
