new file mode 100644
index 0000000..cad4977
--- /dev/null
+++ b/js/delivery-notes.js
@@ -0,0 +1,188 @@
+// UI wiring for the encrypted delivery notes widget on the homepage.
+import {
+  SUITES,
+  DEFAULT_SUITE,
+  MAX_NOTE_BYTES,
+  sealNote,
+  openNote,
+  fingerprint,
+  generateRecipientKeyPair,
+  importRecipientPublicKey,
+} from './delivery-notes-crypto.js';
+
+// The store publishes its public keys here. Private keys never touch the browser in production.
+const KEYS_URL = '/keys/delivery-notes.json';
+const STORAGE_KEY = 'dailyGrind.deliveryNote.sealed';
+
+const $ = (id) => document.getElementById(id);
+const form = $('dn-form');
+if (form) init();
+
+function init() {
+  const els = {
+    note: $('dn-note'),
+    ref: $('dn-ref'),
+    suite: $('dn-suite'),
+    counter: $('dn-counter'),
+    status: $('dn-status'),
+    keySource: $('dn-key-source'),
+    fp: $('dn-fingerprint'),
+    output: $('dn-output'),
+    envelope: $('dn-envelope'),
+    copy: $('dn-copy'),
+    submit: $('dn-submit'),
+    demo: $('dn-demo'),
+    decrypt: $('dn-decrypt'),
+    decrypted: $('dn-decrypted'),
+    tamper: $('dn-tamper'),
+  };
+
+  /** @type {Map<string, {suite:string, publicKey:Uint8Array, kid:string, secretKey?:Uint8Array}>} */
+  let recipients = new Map();
+  let demoMode = false;
+  let lastEnvelope = null;
+
+  const setStatus = (msg, kind = 'info') => {
+    els.status.textContent = msg;
+    els.status.dataset.kind = kind;
+  };
+
+  for (const s of Object.values(SUITES)) {
+    const opt = document.createElement('option');
+    opt.value = s.id;
+    opt.textContent = s.label;
+    els.suite.append(opt);
+  }
+  els.suite.value = DEFAULT_SUITE;
+
+  const updateCounter = () => {
+    const n = new TextEncoder().encode(els.note.value).length;
+    els.counter.textContent = `${n} / ${MAX_NOTE_BYTES} bytes`;
+    els.counter.dataset.over = String(n > MAX_NOTE_BYTES);
+  };
+  els.note.addEventListener('input', updateCounter);
+  updateCounter();
+
+  async function showFingerprint() {
+    const r = recipients.get(els.suite.value);
+    if (!r) {
+      els.fp.textContent = 'not published';
+      els.submit.disabled = true;
+      return;
+    }
+    els.submit.disabled = false;
+    els.fp.textContent = await fingerprint(r.suite, r.publicKey);
+    const s = SUITES[r.suite];
+    if (!s.pq) setStatus('Warning: classical-only suite offers no protection against future quantum attacks.', 'warn');
+    else if (els.status.dataset.kind === 'warn') setStatus('');
+  }
+  els.suite.addEventListener('change', showFingerprint);
+
+  async function loadKeys() {
+    try {
+      const res = await fetch(KEYS_URL, { cache: 'no-cache', credentials: 'omit' });
+      if (!res.ok) throw new Error(`HTTP ${res.status}`);
+      const data = await res.json();
+      const loaded = new Map();
+      for (const entry of data.keys ?? []) {
+        try {
+          const k = await importRecipientPublicKey(entry);
+          loaded.set(k.suite, k);
+        } catch (e) {
+          console.warn('Skipping invalid delivery-notes key:', e);
+        }
+      }
+      if (!loaded.size) throw new Error('no usable keys');
+      recipients = loaded;
+      els.keySource.textContent = 'Daily Grind store key (published)';
+    } catch {
+      // No published key available (e.g. local/static preview): use an in-memory demo store so
+      // the full seal/open round trip can be exercised. Demo private keys vanish on reload.
+      demoMode = true;
+      for (const id of Object.keys(SUITES)) recipients.set(id, await generateRecipientKeyPair(id));
+      els.keySource.textContent = 'Demo store key (generated in this tab, memory only)';
+      els.demo.hidden = false;
+    }
+    if (!recipients.has(els.suite.value)) {
+      const first = [DEFAULT_SUITE, ...recipients.keys()].find((id) => recipients.has(id));
+      els.suite.value = first;
+    }
+    await showFingerprint();
+  }
+
+  form.addEventListener('submit', async (ev) => {
+    ev.preventDefault();
+    const recipient = recipients.get(els.suite.value);
+    if (!recipient) return setStatus('No store key available for this protection level.', 'error');
+    const note = els.note.value.trim();
+    if (!note) return setStatus('Please enter a delivery note first.', 'error');
+
+    els.submit.disabled = true;
+    setStatus('Encrypting in your browser…');
+    try {
+      const envelope = await sealNote(note, recipient, els.ref.value.trim());
+      lastEnvelope = envelope;
+      const json = JSON.stringify(envelope, null, 2);
+      els.envelope.textContent = json;
+      els.output.hidden = false;
+      els.decrypted.textContent = '';
+      // Only the sealed envelope is stored; the plaintext is cleared from the form.
+      try {
+        localStorage.setItem(STORAGE_KEY, JSON.stringify(envelope));
+      } catch {
+        /* storage may be unavailable (private mode); the envelope is still shown */
+      }
+      els.note.value = '';
+      updateCounter();
+      setStatus(`Sealed with ${SUITES[envelope.suite].label}. It will be attached to your next order.`, 'ok');
+    } catch (e) {
+      setStatus(`Could not encrypt note: ${e.message}`, 'error');
+    } finally {
+      els.submit.disabled = false;
+    }
+  });
+
+  els.copy.addEventListener('click', async () => {
+    try {
+      await navigator.clipboard.writeText(els.envelope.textContent);
+      setStatus('Encrypted envelope copied to clipboard.', 'ok');
+    } catch {
+      setStatus('Clipboard unavailable; select the text to copy it manually.', 'warn');
+    }
+  });
+
+  async function tryOpen(envelope) {
+    const recipient = recipients.get(envelope.suite);
+    if (!demoMode || !recipient?.secretKey) throw new Error('Store private key not available here');
+    return openNote(envelope, recipient);
+  }
+
+  els.decrypt.addEventListener('click', async () => {
+    if (!lastEnvelope) return;
+    try {
+      els.decrypted.textContent = await tryOpen(lastEnvelope);
+      els.decrypted.dataset.kind = 'ok';
+    } catch (e) {
+      els.decrypted.textContent = e.message;
+      els.decrypted.dataset.kind = 'error';
+    }
+  });
+
+  els.tamper.addEventListener('click', async () => {
+    if (!lastEnvelope) return;
+    // Flip one bit of the ciphertext and change the order reference; both must be rejected.
+    const ct = lastEnvelope.ct;
+    const flipped = (ct[0] === 'A' ? 'B' : 'A') + ct.slice(1);
+    const forged = { ...lastEnvelope, ct: flipped, ref: `${lastEnvelope.ref}-forged` };
+    try {
+      await tryOpen(forged);
+      els.decrypted.textContent = 'Unexpected: tampered note decrypted!';
+      els.decrypted.dataset.kind = 'error';
+    } catch (e) {
+      els.decrypted.textContent = `Tampered copy rejected ✔ (${e.message})`;
+      els.decrypted.dataset.kind = 'ok';
+    }
+  });
+
+  loadKeys().catch((e) => setStatus(`Encrypted notes unavailable: ${e.message}`, 'error'));
+}
