+++ b/scripts/generate-store-keys.js
@@ -0,0 +1,22 @@
+// Generate the store's delivery-notes key pairs.
+//   node scripts/generate-store-keys.js [privateOutFile]
+// Writes the public bundle to keys/delivery-notes.json (served to browsers) and the private keys
+// to the given file (default: store-private-keys.json, git-ignored). Keep the private file only on
+// the fulfilment system that decrypts notes; never deploy it with the website.
+import { writeFileSync, mkdirSync } from 'node:fs';
+
+globalThis.isSecureContext = true;
+const { SUITES, generateRecipientKeyPair, b64uEncode } = await import('../js/delivery-notes-crypto.js');
+
+const privOut = process.argv[2] ?? 'store-private-keys.json';
+const pub = { created: new Date().toISOString(), keys: [] };
+const priv = { created: pub.created, keys: [] };
+for (const id of Object.keys(SUITES)) {
+  const kp = await generateRecipientKeyPair(id);
+  pub.keys.push({ suite: id, kid: kp.kid, publicKey: b64uEncode(kp.publicKey) });
+  priv.keys.push({ suite: id, kid: kp.kid, publicKey: b64uEncode(kp.publicKey), secretKey: b64uEncode(kp.secretKey) });
+}
+mkdirSync('keys', { recursive: true });
+writeFileSync('keys/delivery-notes.json', JSON.stringify(pub, null, 2) + '\n');
+writeFileSync(privOut, JSON.stringify(priv, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
+console.log(`Public keys -> keys/delivery-notes.json\nPrivate keys -> ${privOut} (mode 600)`);
