@@ -0,0 +1,83 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+
+globalThis.isSecureContext = true; // Node exposes Web Crypto but not the browser flag.
+const C = await import('../js/delivery-notes-crypto.js');
+const { SUITES, sealNote, openNote, generateRecipientKeyPair, importRecipientPublicKey, b64uEncode, b64uDecode } = C;
+
+const NOTE = 'Gate code 4821# — leave by the side door. Severe nut allergy 🥜';
+
+for (const id of Object.keys(SUITES)) {
+  test(`${id}: round trip`, async () => {
+    const kp = await generateRecipientKeyPair(id);
+    const env = await sealNote(NOTE, kp, 'DG-1');
+    assert.equal(env.suite, id);
+    assert.equal(env.kid, kp.kid);
+    assert.ok(!JSON.stringify(env).includes('4821'));
+    assert.equal(await openNote(env, kp), NOTE);
+  });
+
+  test(`${id}: fresh randomness per message`, async () => {
+    const kp = await generateRecipientKeyPair(id);
+    const a = await sealNote(NOTE, kp), b = await sealNote(NOTE, kp);
+    assert.notEqual(a.enc, b.enc);
+    assert.notEqual(a.ct, b.ct);
+  });
+
+  test(`${id}: tampering with any field is rejected`, async () => {
+    const kp = await generateRecipientKeyPair(id);
+    const env = await sealNote(NOTE, kp, 'DG-1');
+    const flip = (s) => { const b = b64uDecode(s); b[b.length - 1] ^= 1; return b64uEncode(b); };
+    for (const forged of [
+      { ...env, ct: flip(env.ct) },
+      { ...env, iv: flip(env.iv) },
+      { ...env, enc: flip(env.enc) },
+      { ...env, ref: 'DG-2' },
+    ]) {
+      await assert.rejects(openNote(forged, kp));
+    }
+  });
+
+  test(`${id}: wrong recipient key is rejected`, async () => {
+    const kp = await generateRecipientKeyPair(id);
+    const other = await generateRecipientKeyPair(id);
+    const env = await sealNote(NOTE, kp);
+    await assert.rejects(openNote(env, other), /different key/);
+    // Even if the kid is forged to match, decryption must fail.
+    await assert.rejects(openNote({ ...env, kid: other.kid }, other), /Authentication failed/);
+  });
+}
+
+test('suite downgrade is rejected', async () => {
+  const kp = await generateRecipientKeyPair('XWING');
+  const env = await sealNote(NOTE, kp);
+  await assert.rejects(openNote({ ...env, suite: 'X25519' }, kp), /suite/);
+});
+
+test('padding hides exact length', async () => {
+  const kp = await generateRecipientKeyPair('XWING');
+  const a = await sealNote('a', kp), b = await sealNote('a'.repeat(200), kp);
+  assert.equal(a.ct.length, b.ct.length);
+});
+
+test('input limits', async () => {
+  const kp = await generateRecipientKeyPair('MLKEM768');
+  await assert.rejects(sealNote('', kp), /empty/);
+  await assert.rejects(sealNote('x'.repeat(C.MAX_NOTE_BYTES + 1), kp), /exceeds/);
+  assert.equal(await openNote(await sealNote('x'.repeat(C.MAX_NOTE_BYTES), kp), kp), 'x'.repeat(C.MAX_NOTE_BYTES));
+});
+
+test('public key import validates length and kid', async () => {
+  const kp = await generateRecipientKeyPair('XWING');
+  const entry = { suite: 'XWING', publicKey: b64uEncode(kp.publicKey), kid: kp.kid };
+  const imported = await importRecipientPublicKey(entry);
+  assert.equal(imported.kid, kp.kid);
+  assert.equal(await openNote(await sealNote(NOTE, imported), kp), NOTE);
+  await assert.rejects(importRecipientPublicKey({ ...entry, kid: 'nope' }), /mismatch/);
+  await assert.rejects(importRecipientPublicKey({ ...entry, publicKey: b64uEncode(kp.publicKey.subarray(1)) }), /length/);
+  await assert.rejects(importRecipientPublicKey({ ...entry, suite: '__proto__' }), /Unsupported/);
+});
+
+test('X25519 low-order public key is rejected', async () => {
+  await assert.rejects(sealNote(NOTE, { suite: 'X25519', publicKey: new Uint8Array(32), kid: 'x' }));
+});
