@@ -0,0 +1,24 @@
+// Web Worker that runs the smallpt WebAssembly module off the main thread.
+// Each worker renders the rows it is assigned and posts them back one by one.
+importScripts('../wasm/smallpt.js');
+
+const ready = createSmallpt({
+  locateFile: (path) => new URL('../wasm/' + path, self.location.href).href,
+});
+
+self.onmessage = async (e) => {
+  const { jobId, width, height, spp, colors, rows, seed } = e.data;
+  const M = await ready;
+
+  M._reset_colors();
+  if (colors) colors.forEach(([i, r, g, b]) => M._set_sphere_color(i, r, g, b));
+
+  const ptr = M._setup(width, height, spp);
+  for (const y of rows) {
+    M._render_row(y, seed);
+    // Copy out of wasm memory (HEAPU8 is re-read in case memory grew).
+    const data = M.HEAPU8.slice(ptr, ptr + width * 4);
+    self.postMessage({ type: 'row', jobId, y, data }, [data.buffer]);
+  }
+  self.postMessage({ type: 'done', jobId });
+};
