+// Drives the smallpt WebAssembly path tracer: splits the image across a pool of
+// Web Workers and paints rows onto the canvas as they finish.
+(() => {
+  const canvas = document.getElementById('tracer-canvas');
+  const button = document.getElementById('tracer-randomize');
+  const sppSelect = document.getElementById('tracer-spp');
+  const status = document.getElementById('tracer-status');
+  const swatches = document.getElementById('tracer-swatches');
+  if (!canvas || !window.Worker || !window.WebAssembly) {
+    if (status) status.textContent = 'Your browser does not support WebAssembly workers.';
+    return;
+  }
+
+  const ctx = canvas.getContext('2d');
+  const W = canvas.width;
+  const H = canvas.height;
+  const POOL = Math.max(1, Math.min(navigator.hardwareConcurrency || 4, 16));
+
+  // Sphere indices in smallpt's scene (index 3 is the black front wall,
+  // index 8 is the light; both are left alone).
+  const DIFFUSE = [0, 1, 2, 4, 5]; // left, right, back, floor, ceiling walls
+  const SHINY = [6, 7];            // mirror ball, glass ball
+
+  let workers = [];
+  let jobId = 0;
+
+  function spawnPool() {
+    workers.forEach((w) => w.terminate());
+    workers = Array.from({ length: POOL }, () => {
+      const w = new Worker('js/smallpt-worker.js');
+      w.onmessage = onMessage;
+      w.onerror = (e) => {
+        status.textContent = 'Renderer error: ' + (e.message || 'failed to load');
+      };
+      return w;
+    });
+  }
+
+  function randomColors() {
+    // Diffuse walls: any hue, kept below 1 so Russian roulette converges.
+    const rand = (lo, hi) => lo + Math.random() * (hi - lo);
+    const out = DIFFUSE.map((i) => [i, rand(0.05, 0.9), rand(0.05, 0.9), rand(0.05, 0.9)]);
+    // Mirror / glass: bright tints so they stay recognizably reflective.
+    SHINY.forEach((i) => out.push([i, rand(0.4, 0.999), rand(0.4, 0.999), rand(0.4, 0.999)]));
+    return out;
+  }
+
+  function showSwatches(colors) {
+    const list = colors || [
+      [0, 0.75, 0.25, 0.25], [1, 0.25, 0.25, 0.75], [2, 0.75, 0.75, 0.75],
+      [4, 0.75, 0.75, 0.75], [5, 0.75, 0.75, 0.75], [6, 0.999, 0.999, 0.999],
+      [7, 0.999, 0.999, 0.999],
+    ];
+    swatches.innerHTML = '';
+    list.forEach(([, r, g, b]) => {
+      const s = document.createElement('span');
+      const c = (v) => Math.round(Math.pow(v, 1 / 2.2) * 255);
+      s.style.background = `rgb(${c(r)}, ${c(g)}, ${c(b)})`;
+      swatches.appendChild(s);
+    });
+  }
+
+  let current = null;
+
+  function render(colors) {
+    // Restart the pool if a previous render is still running (workers render
+    // synchronously, so terminating them is the only way to cancel).
+    if (!workers.length || (current && current.remaining > 0)) spawnPool();
+
+    const spp = parseInt(sppSelect.value, 10);
+    const id = ++jobId;
+    current = { id, spp, remaining: H, doneWorkers: 0, start: performance.now() };
+    showSwatches(colors);
+    ctx.fillStyle = '#111';
+    ctx.fillRect(0, 0, W, H);
+    status.textContent = `Rendering ${W}×${H} at ${spp} spp on ${POOL} thread${POOL > 1 ? 's' : ''}…`;
+
+    const seed = Math.floor(Math.random() * 65536);
+    workers.forEach((w, k) => {
+      const rows = [];
+      for (let y = k; y < H; y += POOL) rows.push(y); // interleave rows
+      w.postMessage({ jobId: id, width: W, height: H, spp, colors, rows, seed });
+    });
+  }
+
+  function onMessage(e) {
+    const msg = e.data;
+    if (!current || msg.jobId !== current.id) return; // stale result
+    if (msg.type === 'row') {
+      ctx.putImageData(new ImageData(new Uint8ClampedArray(msg.data.buffer), W, 1), 0, msg.y);
+      current.remaining--;
+      const pct = (100 * (H - current.remaining) / H).toFixed(0);
+      status.textContent = `Rendering ${W}×${H} at ${current.spp} spp… ${pct}%`;
+    } else if (msg.type === 'done' && ++current.doneWorkers === workers.length) {
+      const secs = ((performance.now() - current.start) / 1000).toFixed(2);
+      status.textContent = `Done: ${W}×${H} at ${current.spp} spp in ${secs}s.`;
+    }
+  }
+
+  button.addEventListener('click', () => render(randomColors()));
+  render(null); // first render uses smallpt's original scene colors
+})();
