+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Load</title>
+</head>
+<body>
+  <button type="button" id="load">Load data</button>
+  <output id="out" aria-live="polite"></output>
+  <script>
+    const out = document.getElementById('out');
+
+    document.getElementById('load').addEventListener('click', async () => {
+      // Mission-critical data: dispatched first, at high priority.
+      const dataRequest = fetch('/api/data', { priority: 'high' });
+
+      // Analytics: fire-and-forget, deprioritized so it doesn't compete with the critical request.
+      fetch('/api/analytics', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ click: 1 }),
+        priority: 'low',
+        keepalive: true
+      }).catch(() => {});
+
+      try {
+        const res = await dataRequest;
+        if (!res.ok) throw new Error(`HTTP ${res.status}`);
+        out.textContent = await res.text();
+      } catch (err) {
+        out.textContent = `Failed to load data: ${err.message}`;
+      }
+    });
+  </script>
+</body>
+</html>

