index 0000000..a15c510
--- /dev/null
+++ b/js/signing-core.js
@@ -0,0 +1,418 @@
+// The Daily Grind — digital signatures for receipts & gift vouchers.
+//
+// Pure crypto/data module (no DOM). Works in modern browsers and Node >= 20.
+//
+// Supported algorithms:
+//   - ECDSA-P256-SHA256  classical, WebCrypto (FIPS 186-5)
+//   - Ed25519            classical, WebCrypto (RFC 8032), where supported
+//   - ML-DSA-65          quantum-resistant (FIPS 204), via vendored @noble/post-quantum
+//
+// Signed envelope format ("daily-grind-signed/v1"):
+//   { format, alg, kid, publicKey, payload, signature }
+// The signature covers a domain-separated, canonical encoding of
+// (format, alg, kid, payload). `kid` is the SHA-256 fingerprint of
+// (alg, publicKey) so the key and algorithm cannot be swapped independently.
+//
+// NOTE: a valid signature proves *integrity* and that the holder of the
+// embedded key signed it. *Authenticity* (that the key belongs to The Daily
+// Grind) additionally requires the key fingerprint to be in a trusted set —
+// verifyEnvelope() reports both separately.
+
+export const FORMAT = 'daily-grind-signed/v1';
+const DOMAIN = 'DailyGrind-Signature-v1';
+const ML_DSA_MODULE = '../vendor/noble-ml-dsa-0.7.1.min.js';
+
+export const MAX_TOKEN_CHARS = 64 * 1024;
+const CLOCK_SKEW_MS = 5 * 60 * 1000;
+
+export const ALGORITHMS = {
+  'ECDSA-P256-SHA256': {
+    label: 'ECDSA P-256 (classical)',
+    family: 'webcrypto',
+    quantumResistant: false,
+    genParams: { name: 'ECDSA', namedCurve: 'P-256' },
+    importParams: { name: 'ECDSA', namedCurve: 'P-256' },
+    signParams: { name: 'ECDSA', hash: 'SHA-256' },
+    sigLen: 64,
+  },
+  Ed25519: {
+    label: 'Ed25519 (classical)',
+    family: 'webcrypto',
+    quantumResistant: false,
+    genParams: { name: 'Ed25519' },
+    importParams: { name: 'Ed25519' },
+    signParams: { name: 'Ed25519' },
+    sigLen: 64,
+  },
+  'ML-DSA-65': {
+    label: 'ML-DSA-65 (quantum-resistant, FIPS 204)',
+    family: 'noble',
+    quantumResistant: true,
+    pubLen: 1952,
+    sigLen: 3309,
+  },
+};
+
+const subtle = globalThis.crypto.subtle;
+const te = new TextEncoder();
+const td = new TextDecoder('utf-8', { fatal: true });
+
+// ---------------------------------------------------------------- encoding
+
+export function b64uEncode(bytes) {
+  let bin = '';
+  for (let i = 0; i < bytes.length; i += 0x8000) {
+    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
+  }
+  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
+}
+
+export function b64uDecode(str) {
+  if (typeof str !== 'string' || !/^[A-Za-z0-9_-]*$/.test(str)) {
+    throw new Error('Invalid base64url data');
+  }
+  const b64 = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
+  const bin = atob(b64);
+  const out = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
+  return out;
+}
+
+const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
+
+/**
+ * Deterministic JSON: object keys sorted, no whitespace. Only strings,
+ * safe integers, booleans, null, arrays and plain objects are allowed
+ * (money is always integer cents, so floats are rejected outright).
+ */
+export function canonicalize(value) {
+  if (value === null || typeof value === 'boolean') return JSON.stringify(value);
+  if (typeof value === 'string') return JSON.stringify(value);
+  if (typeof value === 'number') {
+    if (!Number.isSafeInteger(value)) throw new Error('Only safe integers are allowed in signed data');
+    return String(value);
+  }
+  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
+  if (typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
+    const keys = Object.keys(value).sort();
+    return '{' + keys.map((k) => JSON.stringify(k) + ':' + canonicalize(value[k])).join(',') + '}';
+  }
+  throw new Error('Unsupported value in signed data');
+}
+
+function signingInput(alg, kid, payload) {
+  return te.encode([DOMAIN, FORMAT, alg, kid, canonicalize(payload)].join('\n'));
+}
+
+// ---------------------------------------------------------------- keys
+
+let mlDsaPromise;
+async function mlDsa() {
+  mlDsaPromise ||= import(new URL(ML_DSA_MODULE, import.meta.url).href).then((m) => m.ml_dsa65);
+  return mlDsaPromise;
+}
+
+export async function fingerprint(alg, publicKeyBytes) {
+  const prefix = te.encode(alg + '\n');
+  const buf = new Uint8Array(prefix.length + publicKeyBytes.length);
+  buf.set(prefix);
+  buf.set(publicKeyBytes, prefix.length);
+  return toHex(new Uint8Array(await subtle.digest('SHA-256', buf)));
+}
+
+/** Human-friendly short fingerprint, e.g. "3F9A-12C0-77B1-04DE". */
+export const shortFingerprint = (kid) =>
+  kid.slice(0, 16).toUpperCase().match(/.{4}/g).join('-');
+
+const algSupportCache = new Map();
+export async function isAlgorithmSupported(alg) {
+  const spec = ALGORITHMS[alg];
+  if (!spec) return false;
+  if (spec.family === 'noble') return true;
+  if (!algSupportCache.has(alg)) {
+    algSupportCache.set(
+      alg,
+      subtle.generateKey(spec.genParams, false, ['sign', 'verify']).then(() => true, () => false),
+    );
+  }
+  return algSupportCache.get(alg);
+}
+
+/**
+ * Generate a signing key pair. WebCrypto private keys are created
+ * NON-extractable (they can be stored in IndexedDB but never exported).
+ * Returns { alg, kid, publicKey: Uint8Array, privateKey: CryptoKey|Uint8Array, createdAt }.
+ */
+export async function generateSigningKey(alg) {
+  const spec = ALGORITHMS[alg];
+  if (!spec) throw new Error(`Unknown algorithm: ${alg}`);
+  let publicKey, privateKey;
+  if (spec.family === 'webcrypto') {
+    const kp = await subtle.generateKey(spec.genParams, false, ['sign', 'verify']);
+    publicKey = new Uint8Array(await subtle.exportKey('spki', kp.publicKey));
+    privateKey = kp.privateKey;
+  } else {
+    const ml = await mlDsa();
+    const kp = ml.keygen(); // seed from crypto.getRandomValues
+    publicKey = kp.publicKey;
+    privateKey = kp.secretKey;
+  }
+  return { alg, kid: await fingerprint(alg, publicKey), publicKey, privateKey, createdAt: new Date().toISOString() };
+}
+
+async function rawSign(alg, privateKey, data) {
+  const spec = ALGORITHMS[alg];
+  if (spec.family === 'webcrypto') {
+    return new Uint8Array(await subtle.sign(spec.signParams, privateKey, data));
+  }
+  return (await mlDsa()).sign(data, privateKey);
+}
+
+async function rawVerify(alg, publicKeyBytes, signature, data) {
+  const spec = ALGORITHMS[alg];
+  if (spec.sigLen && signature.length !== spec.sigLen) return false;
+  if (spec.family === 'webcrypto') {
+    let key;
+    try {
+      key = await subtle.importKey('spki', publicKeyBytes, spec.importParams, false, ['verify']);
+    } catch {
+      return false;
+    }
+    return subtle.verify(spec.signParams, key, signature, data);
+  }
+  if (publicKeyBytes.length !== spec.pubLen) return false;
+  try {
+    return (await mlDsa()).verify(signature, data, publicKeyBytes);
+  } catch {
+    return false;
+  }
+}
+
+/** Shareable public-key descriptor (safe to publish). */
+export function exportPublicKey(key) {
+  return { format: 'daily-grind-pubkey/v1', alg: key.alg, kid: key.kid, publicKey: b64uEncode(key.publicKey) };
+}
+
+/** Parse + validate a public-key descriptor; recomputes the fingerprint. */
+export async function importPublicKey(json) {
+  const obj = typeof json === 'string' ? JSON.parse(json) : json;
+  if (!obj || obj.format !== 'daily-grind-pubkey/v1') throw new Error('Not a Daily Grind public key');
+  if (!ALGORITHMS[obj.alg]) throw new Error(`Unsupported algorithm: ${obj.alg}`);
+  const pub = b64uDecode(obj.publicKey);
+  const kid = await fingerprint(obj.alg, pub);
+  if (obj.kid && obj.kid !== kid) throw new Error('Public key fingerprint mismatch');
+  return { alg: obj.alg, kid, publicKey: obj.publicKey };
+}
+
+// ---------------------------------------------------------------- sign / verify
+
+export async function signPayload(key, payload) {
+  validatePayload(payload); // never sign malformed documents
+  const signature = await rawSign(key.alg, key.privateKey, signingInput(key.alg, key.kid, payload));
+  return {
+    format: FORMAT,
+    alg: key.alg,
+    kid: key.kid,
+    publicKey: b64uEncode(key.publicKey),
+    payload,
+    signature: b64uEncode(signature),
+  };
+}
+
+/** Compact, copy-paste friendly token: "DG1." + base64url(JSON envelope). */
+export const envelopeToToken = (env) => 'DG1.' + b64uEncode(te.encode(JSON.stringify(env)));
+
+/** Accepts either a JSON envelope or a "DG1." token. */
+export function parseEnvelope(input) {
+  if (typeof input !== 'string') throw new Error('Expected text input');
+  const text = input.trim();
+  if (!text) throw new Error('Nothing to verify');
+  if (text.length > MAX_TOKEN_CHARS) throw new Error('Input is too large');
+  let json = text;
+  if (text.startsWith('DG1.')) json = td.decode(b64uDecode(text.slice(4).replace(/\s+/g, '')));
+  let env;
+  try {
+    env = JSON.parse(json);
+  } catch {
+    throw new Error('Not valid JSON or a DG1 token');
+  }
+  if (!env || typeof env !== 'object' || Array.isArray(env)) throw new Error('Malformed envelope');
+  return env;
+}
+
+/**
+ * Verify an envelope.
+ * @param env           parsed envelope
+ * @param trustedKids   Set/array of trusted key fingerprints (hex)
+ * @param now           Date used for validity checks
+ * @returns {{ status: 'valid'|'untrusted'|'invalid', signatureValid, trusted,
+ *             errors: string[], warnings: string[], payload }}
+ */
+export async function verifyEnvelope(env, trustedKids = [], now = new Date()) {
+  const trustedSet = trustedKids instanceof Set ? trustedKids : new Set(trustedKids);
+  const errors = [];
+  const warnings = [];
+  const result = (signatureValid, trusted) => ({
+    status: errors.length || !signatureValid ? 'invalid' : trusted ? 'valid' : 'untrusted',
+    signatureValid,
+    trusted,
+    errors,
+    warnings,
+    payload: env && env.payload,
+    alg: env && env.alg,
+    kid: env && env.kid,
+  });
+
+  if (!env || env.format !== FORMAT) {
+    errors.push('Unknown document format');
+    return result(false, false);
+  }
+  if (!Object.prototype.hasOwnProperty.call(ALGORITHMS, env.alg)) {
+    errors.push(`Unsupported or disallowed algorithm "${String(env.alg)}"`);
+    return result(false, false);
+  }
+  if (typeof env.kid !== 'string' || typeof env.publicKey !== 'string' || typeof env.signature !== 'string') {
+    errors.push('Envelope is missing key or signature fields');
+    return result(false, false);
+  }
+
+  let pub, sig;
+  try {
+    pub = b64uDecode(env.publicKey);
+    sig = b64uDecode(env.signature);
+  } catch {
+    errors.push('Key or signature is not valid base64url');
+    return result(false, false);
+  }
+
+  const kid = await fingerprint(env.alg, pub);
+  if (kid !== env.kid) {
+    errors.push('Key fingerprint does not match the embedded public key');
+    return result(false, false);
+  }
+
+  let data;
+  try {
+    data = signingInput(env.alg, env.kid, env.payload);
+  } catch (e) {
+    errors.push(`Payload cannot be canonicalized: ${e.message}`);
+    return result(false, false);
+  }
+
+  const signatureValid = await rawVerify(env.alg, pub, sig, data);
+  if (!signatureValid) {
+    errors.push('Signature does not match — the document was altered or signed with a different key');
+    return result(false, false);
+  }
+
+  // Signature is good; now check business rules on the signed content.
+  try {
+    validatePayload(env.payload);
+  } catch (e) {
+    errors.push(e.message);
+  }
+  if (!errors.length) checkValidity(env.payload, now, errors, warnings);
+
+  const trusted = trustedSet.has(kid);
+  if (!trusted) warnings.push('Signed by a key that is not in your trusted Daily Grind key list');
+  if (!ALGORITHMS[env.alg].quantumResistant) {
+    warnings.push('Classical signature — not resistant to future quantum attacks');
+  }
+  return result(true, trusted);
+}
+
+// ---------------------------------------------------------------- documents
+
+const isStr = (v, max = 200) => typeof v === 'string' && v.length <= max;
+const isCents = (v) => Number.isSafeInteger(v) && v >= 0 && v <= 100_000_000;
+const isIso = (v) => isStr(v, 40) && !Number.isNaN(Date.parse(v));
+
+/** Throws if the payload is not a well-formed receipt or voucher. */
+export function validatePayload(p) {
+  if (!p || typeof p !== 'object' || Array.isArray(p)) throw new Error('Payload must be an object');
+  if (!isStr(p.id, 64) || !isIso(p.issuedAt) || p.currency !== 'USD' || !isStr(p.issuer, 80)) {
+    throw new Error('Payload is missing required fields');
+  }
+  if (p.type === 'receipt') {
+    if (!Array.isArray(p.items) || p.items.length === 0 || p.items.length > 50) throw new Error('Receipt has no items');
+    let subtotal = 0;
+    for (const it of p.items) {
+      if (!it || !isStr(it.name, 80) || !Number.isSafeInteger(it.qty) || it.qty < 1 || it.qty > 99 || !isCents(it.unitCents)) {
+        throw new Error('Receipt contains an invalid line item');
+      }
+      subtotal += it.qty * it.unitCents;
+    }
+    if (p.customer !== undefined && !isStr(p.customer, 80)) throw new Error('Invalid customer name');
+    if (!isCents(p.subtotalCents) || !isCents(p.taxCents) || !isCents(p.totalCents)) throw new Error('Invalid receipt totals');
+    if (subtotal !== p.subtotalCents || p.subtotalCents + p.taxCents !== p.totalCents) {
+      throw new Error('Receipt totals do not add up');
+    }
+  } else if (p.type === 'voucher') {
+    if (!isCents(p.valueCents) || p.valueCents < 100) throw new Error('Invalid voucher value');
+    if (!isStr(p.recipient, 80) || !isStr(p.message ?? '', 280)) throw new Error('Invalid voucher recipient/message');
+    if (!isIso(p.expiresAt)) throw new Error('Voucher has no valid expiry date');
+    if (Date.parse(p.expiresAt) <= Date.parse(p.issuedAt)) throw new Error('Voucher expires before it was issued');
+  } else {
+    throw new Error('Unknown document type');
+  }
+}
+
+function checkValidity(p, now, errors, warnings) {
+  if (Date.parse(p.issuedAt) > now.getTime() + CLOCK_SKEW_MS) {
+    errors.push('Document is dated in the future');
+  }
+  if (p.type === 'voucher' && Date.parse(p.expiresAt) < now.getTime()) {
+    errors.push(`Voucher expired on ${new Date(p.expiresAt).toLocaleDateString()}`);
+  }
+  if (p.type === 'voucher') warnings.push('Signatures prove authenticity, not that a voucher is unspent — redemption must be checked at the till');
+}
+
+const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
+export function randomCode(groups = 2, size = 4) {
+  const bytes = crypto.getRandomValues(new Uint8Array(groups * size));
+  const chars = Array.from(bytes, (b) => CROCKFORD[b & 31]).join('');
+  return chars.match(new RegExp(`.{${size}}`, 'g')).join('-');
+}
+
+export const ISSUER = 'The Daily Grind Coffee Co.';
+export const TAX_RATE_BPS = 875; // 8.75%
+
+export function buildReceipt({ items, customer }, now = new Date()) {
+  const lines = items
+    .filter((i) => i.qty > 0)
+    .map((i) => ({ name: i.name, qty: i.qty, unitCents: i.unitCents }));
+  const subtotalCents = lines.reduce((s, i) => s + i.qty * i.unitCents, 0);
+  const taxCents = Math.round((subtotalCents * TAX_RATE_BPS) / 10_000);
+  const p = {
+    type: 'receipt',
+    id: 'DG-R-' + randomCode(2, 4),
+    issuer: ISSUER,
+    issuedAt: now.toISOString(),
+    currency: 'USD',
+    items: lines,
+    subtotalCents,
+    taxCents,
+    totalCents: subtotalCents + taxCents,
+  };
+  if (customer) p.customer = customer;
+  return p;
+}
+
+export function buildVoucher({ valueCents, recipient, message, expiresOn }, now = new Date()) {
+  // expiresOn is "YYYY-MM-DD"; voucher is valid through the end of that day (UTC).
+  const expiresAt = new Date(`${expiresOn}T23:59:59.999Z`);
+  if (Number.isNaN(expiresAt.getTime())) throw new Error('Choose a valid expiry date');
+  return {
+    type: 'voucher',
+    id: 'DG-V-' + randomCode(3, 4),
+    issuer: ISSUER,
+    issuedAt: now.toISOString(),
+    currency: 'USD',
+    valueCents,
+    recipient,
+    message: message || '',
+    expiresAt: expiresAt.toISOString(),
+  };
+}
+
+export const formatCents = (c) => `$${(c / 100).toFixed(2)}`;
diff --git a/js/signing-ui.js b/js/signing-ui.js
new file mode 100644
index 0000000..d764fea
--- /dev/null
+++ b/js/signing-ui.js
@@ -0,0 +1,390 @@
+// UI wiring for signed receipts & gift vouchers on the homepage.
+// All untrusted (pasted) content is rendered with textContent only.
+
+import {
+  ALGORITHMS,
+  isAlgorithmSupported,
+  generateSigningKey,
+  exportPublicKey,
+  importPublicKey,
+  signPayload,
+  envelopeToToken,
+  parseEnvelope,
+  verifyEnvelope,
+  buildReceipt,
+  buildVoucher,
+  shortFingerprint,
+  formatCents,
+  TAX_RATE_BPS,
+  MAX_TOKEN_CHARS,
+} from './signing-core.js';
+import { openKeyStore } from './keystore.js';
+
+const MENU = [
+  { name: 'Maple Oat Latte', unitCents: 575 },
+  { name: 'Dark Roast Espresso', unitCents: 350 },
+  { name: 'Cold Brew', unitCents: 495 },
+  { name: 'Butter Croissant', unitCents: 395 },
+];
+
+const $ = (id) => document.getElementById(id);
+
+function el(tag, props = {}, ...children) {
+  const node = document.createElement(tag);
+  for (const [k, v] of Object.entries(props)) {
+    if (k === 'class') node.className = v;
+    else if (k in node) node[k] = v;
+    else node.setAttribute(k, v);
+  }
+  for (const c of children.flat()) {
+    if (c != null && c !== false) node.append(c instanceof Node ? c : String(c));
+  }
+  return node;
+}
+
+function setStatus(node, msg, isError = false) {
+  node.textContent = msg;
+  node.classList.toggle('error', isError);
+}
+
+function algBadge(alg) {
+  const pq = ALGORITHMS[alg]?.quantumResistant;
+  return el('span', { class: `badge ${pq ? 'pq' : 'classic'}` }, pq ? 'Post-quantum' : 'Classical');
+}
+
+function download(filename, text) {
+  const url = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
+  const a = el('a', { href: url, download: filename });
+  document.body.append(a);
+  a.click();
+  a.remove();
+  setTimeout(() => URL.revokeObjectURL(url), 1000);
+}
+
+async function copyText(text, statusNode) {
+  try {
+    await navigator.clipboard.writeText(text);
+    setStatus(statusNode, 'Copied to clipboard.');
+  } catch {
+    setStatus(statusNode, 'Could not access the clipboard — select the text and copy manually.', true);
+  }
+}
+
+async function init() {
+  if (!globalThis.crypto?.subtle) {
+    for (const id of ['key-status', 'issue-status']) {
+      setStatus($(id), 'Digital signatures need a secure context (HTTPS) and a modern browser.', true);
+    }
+    $('key-generate').disabled = true;
+    $('verify-btn').disabled = true;
+    return;
+  }
+
+  const store = await openKeyStore();
+  let activeKey = await store.getActiveKey();
+  let trusted = await store.listTrusted();
+  let lastEnvelope = null;
+
+  // ------------------------------------------------------------ key panel
+
+  const algSelect = $('key-alg');
+  for (const opt of algSelect.options) {
+    if (!(await isAlgorithmSupported(opt.value))) {
+      opt.disabled = true;
+      opt.textContent += ' (not supported in this browser)';
+    }
+  }
+
+  function renderKey() {
+    const info = $('key-info');
+    const hasKey = Boolean(activeKey);
+    info.hidden = !hasKey;
+    $('key-export').disabled = !hasKey;
+    $('key-delete').disabled = !hasKey;
+    document.querySelectorAll('.sign-btn').forEach((b) => (b.disabled = !hasKey));
+    if (!hasKey) {
+      setStatus($('issue-status'), 'Generate a store signing key first (step 1).');
+      return;
+    }
+    if ($('issue-status').textContent.startsWith('Generate')) setStatus($('issue-status'), '');
+    algSelect.value = activeKey.alg;
+    info.replaceChildren(
+      el('dl', {},
+        el('dt', {}, 'Algorithm'), el('dd', {}, ALGORITHMS[activeKey.alg].label, ' ', algBadge(activeKey.alg)),
+        el('dt', {}, 'Fingerprint'), el('dd', { class: 'mono', title: activeKey.kid }, shortFingerprint(activeKey.kid)),
+        el('dt', {}, 'Created'), el('dd', {}, new Date(activeKey.createdAt).toLocaleString()),
+        el('dt', {}, 'Storage'), el('dd', {}, store.persistent ? 'This browser (IndexedDB)' : 'Memory only — lost on reload'),
+      ),
+    );
+  }
+
+  $('key-generate').addEventListener('click', async () => {
+    const alg = algSelect.value;
+    if (activeKey && !confirm('Replace the current signing key? Documents it already signed will still verify, because its public key stays trusted.')) return;
+    const btn = $('key-generate');
+    btn.disabled = true;
+    setStatus($('key-status'), 'Generating key…');
+    try {
+      const key = await generateSigningKey(alg);
+      await store.saveActiveKey(key);
+      await store.addTrusted({ ...exportPublicKey(key), label: 'This store' });
+      activeKey = key;
+      trusted = await store.listTrusted();
+      renderKey();
+      renderTrusted();
+      setStatus($('key-status'), `New ${alg} key ready.`);
+    } catch (e) {
+      setStatus($('key-status'), `Key generation failed: ${e.message}`, true);
+    } finally {
+      btn.disabled = false;
+    }
+  });
+
+  $('key-export').addEventListener('click', () => {
+    if (!activeKey) return;
+    const json = JSON.stringify(exportPublicKey(activeKey), null, 2);
+    download(`daily-grind-pubkey-${activeKey.kid.slice(0, 8)}.json`, json);
+    setStatus($('key-status'), 'Public key exported. Publish it so customers can verify your documents.');
+  });
+
+  $('key-delete').addEventListener('click', async () => {
+    if (!activeKey) return;
+    if (!confirm('Delete the private signing key from this browser? This cannot be undone.')) return;
+    await store.deleteKey(activeKey.kid);
+    activeKey = null;
+    renderKey();
+    setStatus($('key-status'), 'Private key deleted. Its public key stays in the trusted list until you remove it.');
+  });
+
+  // ------------------------------------------------------------ issue panel
+
+  const tabs = { receipt: $('tab-receipt'), voucher: $('tab-voucher') };
+  const forms = { receipt: $('form-receipt'), voucher: $('form-voucher') };
+  function selectTab(name) {
+    for (const k of Object.keys(tabs)) {
+      tabs[k].setAttribute('aria-selected', String(k === name));
+      forms[k].hidden = k !== name;
+    }
+  }
+  tabs.receipt.addEventListener('click', () => selectTab('receipt'));
+  tabs.voucher.addEventListener('click', () => selectTab('voucher'));
+
+  const qtyInputs = MENU.map((item, i) => {
+    const input = el('input', { type: 'number', min: '0', max: '99', step: '1', value: i === 0 ? '1' : '0', id: `qty-${i}` });
+    $('receipt-items').append(
+      el('div', { class: 'item-row' },
+        el('label', { htmlFor: `qty-${i}`, style: 'margin:0;font-weight:400' }, item.name),
+        el('span', {}, formatCents(item.unitCents)),
+        input,
+      ),
+    );
+    input.addEventListener('input', renderTotals);
+    return input;
+  });
+
+  function receiptItems() {
+    return MENU.map((m, i) => ({ ...m, qty: Math.max(0, Math.min(99, parseInt(qtyInputs[i].value, 10) || 0)) }));
+  }
+  function renderTotals() {
+    const sub = receiptItems().reduce((s, i) => s + i.qty * i.unitCents, 0);
+    const tax = Math.round((sub * TAX_RATE_BPS) / 10_000);
+    $('receipt-totals').textContent = `Subtotal ${formatCents(sub)} · Tax ${formatCents(tax)} · Total ${formatCents(sub + tax)}`;
+  }
+  renderTotals();
+
+  const expiry = $('voucher-expiry');
+  const today = new Date();
+  expiry.min = today.toISOString().slice(0, 10);
+  expiry.value = new Date(today.getTime() + 365 * 864e5).toISOString().slice(0, 10);
+
+  async function issue(buildFn) {
+    if (!activeKey) return;
+    try {
+      const payload = buildFn();
+      const env = await signPayload(activeKey, payload);
+      lastEnvelope = env;
+      $('signed-token').value = envelopeToToken(env);
+      $('signed-output').hidden = false;
+      setStatus($('issue-status'), `Signed ${payload.type} ${payload.id} with ${env.alg}.`);
+    } catch (e) {
+      setStatus($('issue-status'), e.message, true);
+    }
+  }
+
+  forms.receipt.addEventListener('submit', (e) => {
+    e.preventDefault();
+    const items = receiptItems().filter((i) => i.qty > 0);
+    if (!items.length) return setStatus($('issue-status'), 'Add at least one item to the receipt.', true);
+    issue(() => buildReceipt({ items, customer: $('receipt-customer').value.trim() || undefined }));
+  });
+
+  forms.voucher.addEventListener('submit', (e) => {
+    e.preventDefault();
+    issue(() =>
+      buildVoucher({
+        valueCents: parseInt($('voucher-value').value, 10),
+        recipient: $('voucher-recipient').value.trim(),
+        message: $('voucher-message').value.trim(),
+        expiresOn: expiry.value,
+      }),
+    );
+  });
+
+  $('signed-copy').addEventListener('click', () => copyText($('signed-token').value, $('issue-status')));
+  $('signed-download').addEventListener('click', () => {
+    if (lastEnvelope) download(`${lastEnvelope.payload.id}.json`, JSON.stringify(lastEnvelope, null, 2));
+  });
+  $('signed-to-verify').addEventListener('click', () => {
+    $('verify-input').value = $('signed-token').value;
+    $('verify').scrollIntoView({ behavior: 'smooth', block: 'start' });
+    runVerify();
+  });
+
+  // ------------------------------------------------------------ verify panel
+
+  function renderDocument(p) {
+    if (!p || typeof p !== 'object') return null;
+    const rows = [];
+    const row = (a, b) => rows.push(el('tr', {}, el('td', {}, a), el('td', {}, b)));
+    const money = (c) => (Number.isSafeInteger(c) ? formatCents(c) : '?');
+    if (p.type === 'receipt' && Array.isArray(p.items)) {
+      for (const it of p.items) row(`${it?.qty ?? '?'} × ${it?.name ?? '?'}`, money((it?.qty ?? 0) * (it?.unitCents ?? 0)));
+      row('Subtotal', money(p.subtotalCents));
+      row('Tax', money(p.taxCents));
+      row(el('strong', {}, 'Total'), el('strong', {}, money(p.totalCents)));
+      if (p.customer) row('Customer', String(p.customer));
+    } else if (p.type === 'voucher') {
+      row(el('strong', {}, 'Gift value'), el('strong', {}, money(p.valueCents)));
+      row('Recipient', String(p.recipient ?? ''));
+      if (p.message) row('Message', String(p.message));
+      row('Valid through', p.expiresAt ? new Date(p.expiresAt).toLocaleDateString() : '?');
+    }
+    return el('div', { class: 'doc-view' },
+      el('div', {}, el('strong', {}, p.type === 'voucher' ? 'Gift Voucher ' : 'Receipt '), el('span', { class: 'mono' }, String(p.id ?? ''))),
+      el('div', { style: 'font-size:0.8rem;color:#795548' }, `${String(p.issuer ?? '')} · ${p.issuedAt ? new Date(p.issuedAt).toLocaleString() : ''}`),
+      el('table', {}, el('tbody', {}, rows)),
+    );
+  }
+
+  const HEADINGS = {
+    valid: '✔ Authentic — signed by a trusted Daily Grind key',
+    untrusted: '⚠ Signature valid, but the signing key is not trusted',
+    invalid: '✖ Not valid — do not accept this document',
+  };
+
+  async function runVerify() {
+    const out = $('verify-result');
+    out.replaceChildren(el('p', { class: 'status-msg' }, 'Verifying…'));
+    let env;
+    try {
+      env = parseEnvelope($('verify-input').value);
+    } catch (e) {
+      out.replaceChildren(el('div', { class: 'result invalid' }, el('h4', {}, HEADINGS.invalid), el('div', {}, e.message)));
+      return;
+    }
+    const res = await verifyEnvelope(env, trusted.map((t) => t.kid));
+    const trustedEntry = trusted.find((t) => t.kid === res.kid);
+    const meta = [];
+    if (ALGORITHMS[res.alg]) meta.push(el('div', {}, 'Algorithm: ', String(res.alg), ' ', algBadge(res.alg)));
+    if (typeof res.kid === 'string' && /^[0-9a-f]{64}$/.test(res.kid)) {
+      meta.push(el('div', {}, 'Key: ', el('span', { class: 'mono', title: res.kid }, shortFingerprint(res.kid)),
+        trustedEntry ? ` (${trustedEntry.label || 'trusted'})` : ''));
+    }
+    out.replaceChildren(
+      el('div', { class: `result ${res.status}` },
+        el('h4', {}, HEADINGS[res.status]),
+        meta,
+        res.errors.length ? el('ul', {}, res.errors.map((m) => el('li', {}, m))) : null,
+        res.warnings.length ? el('ul', {}, res.warnings.map((m) => el('li', { style: 'color:#6d4c41' }, m))) : null,
+        res.signatureValid ? renderDocument(res.payload) : null,
+      ),
+    );
+  }
+
+  $('verify-btn').addEventListener('click', runVerify);
+
+  $('verify-file').addEventListener('change', async (e) => {
+    const file = e.target.files?.[0];
+    if (!file) return;
+    if (file.size > MAX_TOKEN_CHARS) {
+      $('verify-result').replaceChildren(el('div', { class: 'result invalid' }, 'File is too large.'));
+      return;
+    }
+    $('verify-input').value = await file.text();
+    e.target.value = '';
+    runVerify();
+  });
+
+  // Demonstrates integrity protection: bump an amount without re-signing.
+  $('verify-tamper').addEventListener('click', () => {
+    let env;
+    try {
+      env = parseEnvelope($('verify-input').value);
+    } catch {
+      $('verify-result').replaceChildren(el('p', { class: 'status-msg error' }, 'Paste or issue a signed document first.'));
+      return;
+    }
+    const p = env.payload || {};
+    if (p.type === 'voucher' && Number.isSafeInteger(p.valueCents)) p.valueCents += 10000;
+    else if (p.type === 'receipt' && Array.isArray(p.items) && p.items[0]) {
+      p.items[0].unitCents = 1;
+      p.subtotalCents = p.items.reduce((s, i) => s + i.qty * i.unitCents, 0);
+      p.taxCents = Math.round((p.subtotalCents * TAX_RATE_BPS) / 10_000);
+      p.totalCents = p.subtotalCents + p.taxCents;
+    } else p.tampered = true;
+    $('verify-input').value = envelopeToToken(env);
+    runVerify();
+  });
+
+  // ------------------------------------------------------------ trusted keys
+
+  function renderTrusted() {
+    const list = $('trusted-list');
+    if (!trusted.length) {
+      list.replaceChildren(el('li', {}, 'No trusted keys yet.'));
+      return;
+    }
+    list.replaceChildren(
+      ...trusted.map((t) => {
+        const rm = el('button', { type: 'button', class: 'danger' }, 'Remove');
+        rm.addEventListener('click', async () => {
+          await store.removeTrusted(t.kid);
+          trusted = await store.listTrusted();
+          renderTrusted();
+        });
+        return el('li', {},
+          el('span', {}, el('span', { class: 'mono', title: t.kid }, shortFingerprint(t.kid)), ` · ${t.alg} · ${t.label || 'Imported'}`),
+          rm,
+        );
+      }),
+    );
+  }
+
+  $('trust-add').addEventListener('click', async () => {
+    try {
+      const raw = $('trust-input').value.trim();
+      if (raw.length > MAX_TOKEN_CHARS) throw new Error('Input is too large');
+      const pk = await importPublicKey(raw);
+      await store.addTrusted({ format: 'daily-grind-pubkey/v1', ...pk, label: 'Imported' });
+      trusted = await store.listTrusted();
+      renderTrusted();
+      $('trust-input').value = '';
+      setStatus($('trust-status'), `Trusted key ${shortFingerprint(pk.kid)} added.`);
+    } catch (e) {
+      setStatus($('trust-status'), e instanceof SyntaxError ? 'Not valid JSON.' : e.message, true);
+    }
+  });
+
+  renderKey();
+  renderTrusted();
+  if (!store.persistent) {
+    setStatus($('key-status'), 'Browser storage is unavailable, so keys last only for this visit.');
+  }
+}
+
+init().catch((e) => {
+  console.error(e);
+  const s = $('key-status');
+  if (s) setStatus(s, `Signing features failed to load: ${e.message}`, true);
+});
+
