       text-decoration: none;
       font-size: 0.85rem;
     }
+    /* Seasonal Favorites carousel */
+    .seasonal-carousel {
+      max-width: 480px;
+      margin: 20px auto 0;
+    }
+
+    .seasonal-viewport {
+      overflow: clip;
+      border-radius: 8px;
+      /* Captured as its own group so the sliding card can be clipped to it */
+      view-transition-name: seasonal-viewport;
+      view-transition-group: contain;
+    }
+
+    .seasonal-card {
+      view-transition-name: seasonal-slide;
+    }
+
+    .seasonal-controls {
+      display: flex;
+      justify-content: space-between;
+      align-items: center;
+      margin-top: 15px;
+    }
+
+    .seasonal-controls button {
+      font: inherit;
+      background: var(--secondary);
+      color: var(--text);
+      border: none;
+      border-radius: 5px;
+      padding: 8px 16px;
+      cursor: pointer;
+      transition: background 0.3s;
+    }
+
+    .seasonal-controls button:hover {
+      background: var(--accent);
+    }
+
+    .seasonal-controls button:focus-visible {
+      outline: 2px solid var(--primary);
+      outline-offset: 2px;
+    }
+
+    .seasonal-status {
+      font-size: 0.9rem;
+    }
+
+    ::view-transition-group-children(seasonal-viewport) {
+      overflow: clip;
+    }
+
+    ::view-transition-group(seasonal-slide) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+    }
+
+    ::view-transition-old(seasonal-slide),
+    ::view-transition-new(seasonal-slide) {
+      animation-duration: 0.4s;
+      animation-timing-function: ease-in-out;
+      animation-fill-mode: both;
+    }
+
+    @keyframes slide-to-left {
+      to { transform: translateX(-100%); }
+    }
+
+    @keyframes slide-from-right {
+      from { transform: translateX(100%); }
+    }
+
+    @keyframes slide-to-right {
+      to { transform: translateX(100%); }
+    }
+
+    @keyframes slide-from-left {
+      from { transform: translateX(-100%); }
+    }
+
+    :active-view-transition-type(forward)::view-transition-old(seasonal-slide) {
+      animation-name: slide-to-left;
+    }
+
+    :active-view-transition-type(forward)::view-transition-new(seasonal-slide) {
+      animation-name: slide-from-right;
+    }
+
+    :active-view-transition-type(backward)::view-transition-old(seasonal-slide) {
+      animation-name: slide-to-right;
+    }
+
+    :active-view-transition-type(backward)::view-transition-new(seasonal-slide) {
+      animation-name: slide-from-left;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      ::view-transition-group(*),
+      ::view-transition-old(*),
+      ::view-transition-new(*) {
+        animation: none !important;
+      }
+    }
