+          <label><input type="radio" name="size" value="medium" data-extra="0.50" checked>Medium +$0.50</label>
+          <label><input type="radio" name="size" value="large" data-extra="1.00">Large +$1</label>
+        </div>
+      </fieldset>
+
+      <div class="qo-row">
+        <div class="qo-field">
+          <label class="qo-label" for="qo-milk">Milk</label>
+          <select id="qo-milk" name="milk">
+            <option value="whole">Whole</option>
+            <option value="oat">Oat</option>
+            <option value="almond">Almond</option>
+            <option value="none">No milk</option>
+          </select>
+        </div>
+        <div class="qo-field" style="flex: 0;">
+          <span class="qo-label" id="qo-qty-label">Qty</span>
+          <div class="qo-stepper" role="group" aria-labelledby="qo-qty-label">
+            <button type="button" id="qo-dec" aria-label="Decrease quantity">&minus;</button>
+            <output id="qo-qty" aria-live="polite">1</output>
+            <button type="button" id="qo-inc" aria-label="Increase quantity">+</button>
+          </div>
+          <input type="hidden" name="qty" id="qo-qty-input" value="1">
+        </div>
+      </div>
+
+      <label class="qo-shot"><input type="checkbox" name="extra-shot" id="qo-shot"> Extra espresso shot (+$0.75)</label>
+
+      <button type="submit" class="qo-primary" id="qo-add">Add to cart — <span id="qo-line-price">$5.75</span></button>
+
+      <section class="qo-cart" aria-labelledby="qo-cart-title">
+        <h3 class="qo-label" id="qo-cart-title">Your cart</h3>
+        <p class="qo-empty" id="qo-empty">Your cart is empty.</p>
+        <ul id="qo-items"></ul>
+        <div class="qo-total"><span>Total</span><span id="qo-total">$0.00</span></div>
+        <button type="button" class="qo-primary qo-checkout" id="qo-checkout" disabled>Checkout</button>
+        <p class="qo-status" id="qo-status" role="status"></p>
+      </section>
+    </form>
+  </aside>
+
+  <div class="visually-hidden" aria-live="polite" id="qo-announcer"></div>
+
+  <script>
+    (() => {
+      const panel = document.querySelector('[data-draggable]');
+      const handle = panel.querySelector('[data-drag-handle]');
+      const grip = document.getElementById('qo-grip');
+      const moveBtn = document.getElementById('qo-move-btn');
+      const moveMenu = document.getElementById('qo-move-menu');
+      const helpBtn = document.getElementById('qo-help-btn');
+      const help = document.getElementById('qo-help');
+      const announcer = document.getElementById('qo-announcer');
+      const STORAGE_KEY = 'dailyGrind.quickOrder.position';
+      const MARGIN = 8;
+      const STEP = 15;
+      const BIG_STEP = 60;
+
+      /* ---------- Dragging (progressive enhancement) ---------- */
+      panel.classList.add('js-drag');
+      grip.hidden = false;
+      moveBtn.hidden = false;
+      helpBtn.hidden = false;
+
+      let announceTimer;
+      function announce(msg) {
+        announcer.textContent = msg;
+        clearTimeout(announceTimer);
+        announceTimer = setTimeout(() => { announcer.textContent = ''; }, 1000);
+      }
+
+      function moveTo(left, top) {
+        const maxLeft = Math.max(MARGIN, window.innerWidth - panel.offsetWidth - MARGIN);
+        const maxTop = Math.max(MARGIN, window.innerHeight - panel.offsetHeight - MARGIN);
+        const x = Math.max(MARGIN, Math.min(left, maxLeft));
+        const y = Math.max(MARGIN, Math.min(top, maxTop));
+        panel.classList.add('is-positioned');
+        panel.style.left = `${x}px`;
+        panel.style.top = `${y}px`;
+        return { x, y };
+      }
+
+      function savePosition() {
+        const rect = panel.getBoundingClientRect();
+        try {
+          localStorage.setItem(STORAGE_KEY, JSON.stringify({ left: rect.left, top: rect.top }));
+        } catch { /* storage unavailable */ }
+      }
+
+      function currentPos() {
+        const rect = panel.getBoundingClientRect();
+        return { left: rect.left, top: rect.top };
+      }
+
+      // Restore saved position, or convert the CSS bottom-right default to left/top.
+      (function initPosition() {
+        let saved = null;
+        try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch { /* ignore */ }
+        if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) {
+          moveTo(saved.left, saved.top);
+        } else {
+          const { left, top } = currentPos();
+          moveTo(left, top);
+        }
+      })();
+
+      let offsetX = 0;
+      let offsetY = 0;
+      let startX = 0;
+      let startY = 0;
+      let dragging = false;
+
+      handle.addEventListener('pointerdown', (event) => {
+        const control = event.target.closest('button, input, select, textarea, a, [role="menu"]');
+        if (event.button !== 0 || (control && control !== grip)) return;
+        const rect = panel.getBoundingClientRect();
+        offsetX = event.clientX - rect.left;
+        offsetY = event.clientY - rect.top;
+        startX = event.clientX;
+        startY = event.clientY;
+        dragging = false;
+        closeMenu();
+        handle.setPointerCapture(event.pointerId);
+        event.preventDefault();
+      });
+
+      handle.addEventListener('pointermove', (event) => {
+        if (!handle.hasPointerCapture(event.pointerId)) return;
+        if (!dragging) {
+          if (Math.hypot(event.clientX - startX, event.clientY - startY) < 4) return;
+          dragging = true;
+          handle.classList.add('dragging');
+        }
+        moveTo(event.clientX - offsetX, event.clientY - offsetY);
+      });
+
+      handle.addEventListener('lostpointercapture', () => {
+        if (dragging) {
+          savePosition();
+          announce('Quick order panel moved');
+        }
+        dragging = false;
+        handle.classList.remove('dragging');
+      });
+
+      // Keyboard movement on the grip button
+      const KEY_DIRS = {
+        ArrowLeft: [-1, 0, 'left'],
+        ArrowRight: [1, 0, 'right'],
+        ArrowUp: [0, -1, 'up'],
+        ArrowDown: [0, 1, 'down'],
+      };
+
+      function nudge(dir, step) {
+        const deltas = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1] }[dir];
+        const { left, top } = currentPos();
+        const before = { left, top };
+        const after = moveTo(left + deltas[0] * step, top + deltas[1] * step);
+        savePosition();
+        const moved = Math.round(after.x) !== Math.round(before.left) || Math.round(after.y) !== Math.round(before.top);
+        announce(moved ? `Quick order panel moved ${dir}` : `Quick order panel is at the ${dir === 'left' || dir === 'right' ? dir : dir === 'up' ? 'top' : 'bottom'} edge`);
+      }
+
+      grip.addEventListener('keydown', (event) => {
+        const dir = KEY_DIRS[event.key];
+        if (!dir) return;
+        event.preventDefault();
+        nudge(dir[2], event.shiftKey ? BIG_STEP : STEP);
+      });
+
+      // Single-pointer alternative: move/dock menu
+      function dock(where) {
+        const [v, h] = where.split('-');
+        const left = h === 'left' ? MARGIN : window.innerWidth;
+        const top = v === 'top' ? (document.querySelector('nav')?.offsetHeight ?? 0) + MARGIN : window.innerHeight;
+        panel.classList.add('is-docking');
+        moveTo(left, top);
+        setTimeout(() => panel.classList.remove('is-docking'), 300);
+        savePosition();
+        announce(`Quick order panel docked ${v} ${h}`);
+      }
+
+      function openMenu() {
+        moveMenu.hidden = false;
+        moveBtn.setAttribute('aria-expanded', 'true');
+        moveMenu.querySelector('button').focus();
+      }
+
+      function closeMenu(returnFocus = false) {
+        if (moveMenu.hidden) return;
+        moveMenu.hidden = true;
+        moveBtn.setAttribute('aria-expanded', 'false');
+        if (returnFocus) moveBtn.focus();
+      }
+
+      moveBtn.addEventListener('click', () => {
+        moveMenu.hidden ? openMenu() : closeMenu();
+      });
+
+      moveMenu.addEventListener('click', (event) => {
+        const btn = event.target.closest('button');
+        if (!btn) return;
+        if (btn.dataset.dock) {
+          dock(btn.dataset.dock);
+          closeMenu(true);
+        } else if (btn.dataset.move) {
+          nudge(btn.dataset.move, BIG_STEP);
+        }
+      });
+
+      moveMenu.addEventListener('keydown', (event) => {
+        const items = [...moveMenu.querySelectorAll('button')];
+        const i = items.indexOf(document.activeElement);
+        if (event.key === 'Escape') {
+          event.preventDefault();
+          closeMenu(true);
+        } else if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
+          event.preventDefault();
+          items[(i + 1) % items.length].focus();
+        } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
+          event.preventDefault();
+          items[(i - 1 + items.length) % items.length].focus();
+        } else if (event.key === 'Home') {
+          event.preventDefault();
+          items[0].focus();
+        } else if (event.key === 'End') {
+          event.preventDefault();
+          items.at(-1).focus();
+        } else if (event.key === 'Tab') {
+          closeMenu();
+        }
+      });
+
+      document.addEventListener('pointerdown', (event) => {
+        if (!moveMenu.contains(event.target) && event.target !== moveBtn) closeMenu();
+      });
+
+      function toggleHelp() {
+        const open = help.hidden;
+        help.hidden = !open;
+        helpBtn.setAttribute('aria-expanded', String(open));
+        reclamp();
+      }
+      helpBtn.addEventListener('click', toggleHelp);
+
+      // Keep the panel reachable when the viewport or panel size changes
+      function reclamp() {
+        const { left, top } = currentPos();
+        moveTo(left, top);
+      }
+      window.addEventListener('resize', reclamp);
+      new ResizeObserver(reclamp).observe(panel);
+
+      /* ---------- Collapse ---------- */
+      const collapseBtn = document.getElementById('qo-collapse');
+      const body = document.getElementById('qo-body');
+      collapseBtn.addEventListener('click', () => {
+        const expanded = collapseBtn.getAttribute('aria-expanded') === 'true';
+        body.hidden = expanded;
+        collapseBtn.setAttribute('aria-expanded', String(!expanded));
+        collapseBtn.setAttribute('aria-label', expanded ? 'Expand quick order' : 'Collapse quick order');
+        collapseBtn.innerHTML = expanded ? '+' : '&minus;';
+      });
+
+      /* ---------- Order logic ---------- */
+      const money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
+      const drinkSelect = document.getElementById('qo-drink-select');
+      const img = document.getElementById('qo-img');
+      const milk = document.getElementById('qo-milk');
+      const shot = document.getElementById('qo-shot');
+      const qtyOut = document.getElementById('qo-qty');
+      const qtyInput = document.getElementById('qo-qty-input');
+      const linePrice = document.getElementById('qo-line-price');
+      const itemsList = document.getElementById('qo-items');
+      const empty = document.getElementById('qo-empty');
+      const totalEl = document.getElementById('qo-total');
+      const countEl = document.getElementById('qo-count');
+      const checkout = document.getElementById('qo-checkout');
+      const status = document.getElementById('qo-status');
+      const CART_KEY = 'dailyGrind.quickOrder.cart';
+      const MAX_QTY = 10;
+
+      let qty = 1;
+      let cart = [];
+      try { cart = JSON.parse(localStorage.getItem(CART_KEY)) || []; } catch { cart = []; }
+
+      function currentConfig() {
+        const opt = drinkSelect.selectedOptions[0];
+        const sizeInput = body.querySelector('input[name="size"]:checked');
+        const unit = parseFloat(opt.dataset.price) + parseFloat(sizeInput.dataset.extra) + (shot.checked ? 0.75 : 0);
+        return {
+          id: crypto.randomUUID?.() ?? String(Date.now() + Math.random()),
+          name: opt.textContent.split(' — ')[0],
+          size: sizeInput.value,
+          milk: milk.value,
+          shot: shot.checked,
+          qty,
+          unit,
+        };
+      }
+
+      function updateLinePrice() {
+        const cfg = currentConfig();
+        linePrice.textContent = money.format(cfg.unit * cfg.qty);
+        qtyOut.textContent = qty;
+        qtyInput.value = qty;
+        img.src = drinkSelect.selectedOptions[0].dataset.img;
+        milk.disabled = drinkSelect.value === 'dark-roast-espresso';
+        if (milk.disabled) milk.value = 'none';
+      }
+
+      function renderCart() {
+        itemsList.replaceChildren(...cart.map((item) => {
+          const li = document.createElement('li');
+          const desc = document.createElement('span');
+          const extras = [item.size, item.milk !== 'none' ? `${item.milk} milk` : null, item.shot ? '+shot' : null].filter(Boolean).join(', ');
+          desc.textContent = `${item.qty}× ${item.name} (${extras})`;
+          const price = document.createElement('span');
+          price.textContent = money.format(item.unit * item.qty);
+          const remove = document.createElement('button');
+          remove.type = 'button';
+          remove.className = 'qo-remove';
+          remove.textContent = '×';
+          remove.setAttribute('aria-label', `Remove ${item.name} from cart`);
+          remove.addEventListener('click', () => {
+            cart = cart.filter((c) => c.id !== item.id);
+            persistCart();
+            renderCart();
+            status.textContent = `Removed ${item.name}.`;
+            (itemsList.querySelector('.qo-remove') || drinkSelect).focus();
+          });
+          li.append(desc, price, remove);
+          return li;
+        }));
+        const count = cart.reduce((n, c) => n + c.qty, 0);
+        const total = cart.reduce((s, c) => s + c.unit * c.qty, 0);
+        empty.hidden = cart.length > 0;
+        totalEl.textContent = money.format(total);
+        countEl.textContent = count;
+        countEl.setAttribute('aria-label', `${count} item${count === 1 ? '' : 's'} in cart`);
+        checkout.disabled = cart.length === 0;
+      }
+
+      function persistCart() {
+        try { localStorage.setItem(CART_KEY, JSON.stringify(cart)); } catch { /* ignore */ }
+      }
+
+      document.getElementById('qo-dec').addEventListener('click', () => {
+        qty = Math.max(1, qty - 1);
+        updateLinePrice();
+      });
+      document.getElementById('qo-inc').addEventListener('click', () => {
+        qty = Math.min(MAX_QTY, qty + 1);
+        updateLinePrice();
+      });
+
+      body.addEventListener('change', updateLinePrice);
+
+      body.addEventListener('submit', (event) => {
+        event.preventDefault();
+        const item = currentConfig();
+        cart.push(item);
+        persistCart();
+        renderCart();
+        status.textContent = `Added ${item.qty}× ${item.name} to your cart.`;
+        qty = 1;
+        updateLinePrice();
+      });
+
+      checkout.addEventListener('click', () => {
+        if (!cart.length) return;
+        const total = totalEl.textContent;
+        cart = [];
+        persistCart();
+        renderCart();
+        status.textContent = `Order placed! ${total} — we'll have it ready for pickup in about 10 minutes.`;
+      });
+
+      updateLinePrice();
+      renderCart();
+    })();
+  </script>
+
 </body>

 </html>

