+          }
+          var data = {};
+          Array.prototype.forEach.call(form.elements, function (f) {
+            if (!f.name) return;
+            data[f.name] = f.type === 'checkbox' ? f.checked : f.value;
+          });
+          try { localStorage.setItem('dg-account', JSON.stringify(data)); } catch (err) { /* ignore */ }
+          status.style.color = '';
+          status.textContent = 'Your changes have been saved.';
+        });
+        return view;
+      }
+
+      /* ---------- Router with a keep-alive view cache ---------- */
+
+      var ROUTES = {
+        home: { title: 'The Daily Grind | Artisanal Coffee' },
+        menu: { title: 'Menu | The Daily Grind', create: createMenu },
+        locations: { title: 'Locations | The Daily Grind', create: createLocations },
+        rewards: { title: 'Rewards | The Daily Grind', create: createRewards },
+        account: { title: 'My Account | The Daily Grind', create: createAccount }
+      };
+
+      // name -> { el, scrollY }. Views are built once and then kept in the
+      // document (hidden) so that returning to them is a cheap attribute toggle
+      // that preserves form input, filters, and scroll position.
+      var cache = { home: { el: document.getElementById('view-home'), scrollY: 0 } };
+      var current = null;
+
+      if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
+
+      function getView(name) {
+        var entry = cache[name];
+        if (entry) return entry;
+        var node = ROUTES[name].create();
+        node.classList.add('view');
+        node.id = 'view-' + name;
+        node.dataset.view = name;
+        node.tabIndex = -1;
+        node.hidden = true;
+        app.appendChild(node);
+        return (cache[name] = { el: node, scrollY: 0 });
+      }
+
+      function parse() {
+        var name = location.hash.replace(/^#\/?/, '').split(/[?#/]/)[0];
+        return ROUTES.hasOwnProperty(name) ? name : 'home';
+      }
+
+      function show(name, focus) {
+        if (name === current) return;
+        var next = getView(name);
+
+        if (current) {
+          var prev = cache[current];
+          prev.scrollY = window.scrollY;
+          prev.el.hidden = true;
+          prev.el.inert = true;
+        }
+
+        next.el.hidden = false;
+        next.el.inert = false;
+        current = name;
+
+        document.title = ROUTES[name].title;
+        navLinks.forEach(function (a) {
+          if (a.dataset.route === name) a.setAttribute('aria-current', 'page');
+          else a.removeAttribute('aria-current');
+        });
+
+        window.scrollTo(0, next.scrollY);
+        if (focus) next.el.focus({ preventScroll: true });
+      }
+
+      window.addEventListener('hashchange', function () { show(parse(), true); });
+
+      // Optionally warm up unvisited views when the browser is idle so even the
+      // first visit is instant.
+      var idle = window.requestIdleCallback || function (cb) { return setTimeout(cb, 200); };
+      function prewarm() {
+        var pending = Object.keys(ROUTES).filter(function (n) { return !cache[n]; });
+        (function step() {
+          var n = pending.shift();
+          if (!n) return;
+          if (!cache[n]) getView(n);
+          idle(step);
+        })();
+      }
+
+      // Support legacy deep links like /menu by mapping them onto hash routes.
+      var legacy = location.pathname.replace(/^\/+|\/+$/g, '');
+      if (!location.hash && ROUTES.hasOwnProperty(legacy) && legacy !== 'home') {
+        history.replaceState(null, '', '/#/' + legacy);
+      }
+
+      show(parse(), false);
+      if (document.readyState === 'complete') idle(prewarm);
+      else window.addEventListener('load', function () { idle(prewarm); });
+    })();
+  </script>
+
 </body>

