+    for (const card of document.querySelectorAll('[data-device]')) {
+      const key = card.dataset.device;
+      const cfg = DEVICES[key];
+      const form = card.querySelector('form');
+      const hostInput = form.elements.host;
+      const portInput = form.elements.port;
+      const connectBtn = card.querySelector('[data-action="connect"]');
+      const actionBtn = card.querySelector(`[data-action="${cfg.action.name}"]`);
+      const statusEl = card.querySelector('.device-status');
+      const detailsEl = card.querySelector('.device-details');
+      const badge = card.querySelector('.badge');
+      let connectedBase = null;
+
+      if (saved[key]?.host && cfg.validateHost(saved[key].host)) hostInput.value = saved[key].host;
+      if (saved[key]?.port) portInput.value = saved[key].port;
