+      const setStatus = (msg, state) => {
+        statusEl.textContent = msg;
+        if (state) {
+          badge.dataset.state = state;
+          badge.textContent = { connecting: 'Connecting…', connected: 'Connected', error: 'Not connected' }[state];
+        }
+      };
+
+      const validate = () => {
+        hostInput.setCustomValidity(cfg.validateHost(hostInput.value) ? '' : cfg.hostError);
+        return form.reportValidity();
+      };
+
+      const connect = async () => {
+        if (!validate()) return;
+        const base = { host: hostInput.value.trim(), port: portInput.value };
+        connectBtn.disabled = true;
+        actionBtn.disabled = true;
+        connectedBase = null;
+        setStatus(`Connecting to the ${cfg.label}… your browser may ask for permission.`, 'connecting');
+        try {
+          const data = await deviceFetch(buildUrl(base.host, base.port, cfg.statusPath), cfg.addressSpace);
