+          saved[key] = base;
+          persist();
+          renderDetails(detailsEl, data);
+          setStatus(`Connected to the ${cfg.label} at ${base.host}:${base.port}.`, 'connected');
+          actionBtn.disabled = false;
+        } catch (err) {
+          detailsEl.hidden = true;
+          setStatus(describeError(err, cfg), 'error');
+          const p = await queryLnaPermission(cfg.permission);
+          if (p.state === 'denied') renderPermission(card, cfg.permission, 'denied');
+        } finally {
+          connectBtn.disabled = false;
+        }
+      };
