+      connectBtn.addEventListener('click', connect);
+      form.addEventListener('submit', (e) => { e.preventDefault(); connect(); });
+      hostInput.addEventListener('input', () => hostInput.setCustomValidity(''));
+
+      actionBtn.addEventListener('click', async () => {
+        if (!connectedBase) return;
+        actionBtn.disabled = true;
+        setStatus(`Sending to the ${cfg.label}…`);
+        try {
+          await deviceFetch(buildUrl(connectedBase.host, connectedBase.port, cfg.action.path), cfg.addressSpace, {
+            method: 'POST',
+            headers: { 'Content-Type': 'application/json' },
+            body: JSON.stringify(cfg.action.body),
+          });
