+  const host = rawHost.trim().toLowerCase();
+  const v4 = parseIPv4(host);
+  if (v4) {
+    const [a, b] = v4;
+    return (
+      a === 10 ||
+      (a === 172 && b >= 16 && b <= 31) ||
+      (a === 192 && b === 168) ||
+      (a === 169 && b === 254)
+    );
+  }
+  const v6 = stripBrackets(host);
+  if (v6.includes(':')) {
+    // Unique local (fc00::/7) and link-local (fe80::/10)
+    return /^f[cd][0-9a-f]{0,2}:/.test(v6) || /^fe[89ab][0-9a-f]?:/.test(v6);
