+import type { APIContext } from 'astro';
+import { getOrCreateAccount, type StoredAccount } from './account-store';
+import { getRpId } from './webauthn';
+
+export function json(body: unknown, status = 200): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' },
+  });
+}
+
+export function error(message: string, status: number): Response {
+  return json({ error: message }, status);
+}
+
+/**
+ * The project disables Astro's built-in origin check, so mutating account endpoints
+ * enforce their own CSRF protection: same-site fetch metadata and a JSON body.
+ */
+export function rejectCrossSite(request: Request): Response | null {
+  const site = request.headers.get('sec-fetch-site');
+  if (site && site !== 'same-origin' && site !== 'none') {
+    return error('Cross-site requests are not allowed.', 403);
+  }
+  const type = request.headers.get('content-type') ?? '';
+  if (!type.toLowerCase().startsWith('application/json')) {
+    return error('Expected a JSON request body.', 415);
+  }
+  return null;
+}
+
+export async function readJson<T = any>(request: Request): Promise<T | null> {
+  try {
+    return (await request.json()) as T;
+  } catch {
+    return null;
+  }
+}
+
+export async function getSignedInUser(context: Pick<APIContext, 'session'>) {
+  return (await context.session?.get('user')) ?? null;
+}
+
+/** Shape of the account returned to the browser — never includes public keys. */
+export function serializeAccount(account: StoredAccount, url: URL) {
+  return {
+    rpId: getRpId(url),
+    username: account.username,
+    userId: account.userId,
+    displayName: account.displayName,
+    passkeys: account.passkeys.map((p) => ({
+      id: p.id,
+      name: p.name,
+      provider: p.provider,
+      transports: p.transports,
+      backupEligible: p.backupEligible,
+      backedUp: p.backedUp,
+      createdAt: p.createdAt,
+      lastUsedAt: p.lastUsedAt,
+    })),
+  };
+}
+
+export type SerializedAccount = ReturnType<typeof serializeAccount>;
+
+export async function loadSignedInAccount(context: Pick<APIContext, 'session'>) {
+  const user = await getSignedInUser(context);
+  if (!user) return null;
+  return getOrCreateAccount(user.username);
+}
