+import { createHash, randomBytes } from 'node:crypto';
+
+export function toBase64Url(bytes: Uint8Array | Buffer): string {
+  return Buffer.from(bytes).toString('base64url');
+}
+
+export function fromBase64Url(value: string): Buffer {
+  return Buffer.from(value, 'base64url');
+}
+
+export function randomBase64Url(size = 32): string {
+  return toBase64Url(randomBytes(size));
+}
+
+/** The relying party ID is the effective domain the reader is visiting. */
+export function getRpId(url: URL): string {
+  return url.hostname;
+}
+
+export const RP_NAME = 'The DevTools Times';
+
+export const SUPPORTED_ALGORITHMS = [-7 /* ES256 */, -8 /* EdDSA */, -257 /* RS256 */];
+
+export interface ParsedAuthenticatorData {
+  rpIdHash: Buffer;
+  userPresent: boolean;
+  userVerified: boolean;
+  backupEligible: boolean;
+  backedUp: boolean;
+  signCount: number;
+  aaguid: string | null;
+}
+
+export function parseAuthenticatorData(data: Buffer): ParsedAuthenticatorData {
+  if (data.length < 37) throw new Error('Authenticator data is too short');
+  const flags = data[32];
+  const attestedCredentialData = (flags & 0x40) !== 0;
+  let aaguid: string | null = null;
+  if (attestedCredentialData && data.length >= 53) {
+    const hex = data.subarray(37, 53).toString('hex');
+    aaguid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
+  }
+  return {
+    rpIdHash: data.subarray(0, 32),
+    userPresent: (flags & 0x01) !== 0,
+    userVerified: (flags & 0x04) !== 0,
+    backupEligible: (flags & 0x08) !== 0,
+    backedUp: (flags & 0x10) !== 0,
+    signCount: data.readUInt32BE(33),
+    aaguid,
+  };
+}
+
+export function sha256(value: string | Buffer): Buffer {
+  return createHash('sha256').update(value).digest();
+}
+
+/** A handful of well-known passkey providers, used to suggest a friendly default name. */
+const KNOWN_AAGUIDS: Record<string, string> = {
+  'ea9b8d66-4d01-1d21-3ce4-b6b48cb575d4': 'Google Password Manager',
+  'adce0002-35bc-c60a-648b-0b25f1f05503': 'Chrome on Mac',
+  'fbfc3007-154e-4ecc-8c0b-6e020557d7bd': 'iCloud Keychain',
+  'dd4ec289-e01d-41c9-bb89-70fa845d4bf2': 'iCloud Keychain',
+  '08987058-cadc-4b81-b6e1-30de50dcbe96': 'Windows Hello',
+  '9ddd1817-af5a-4672-a2b9-3e3dd95000a9': 'Windows Hello',
+  '6028b017-b1d4-4c02-b4b3-afcdafc96bb2': 'Windows Hello',
+  'bada5566-a7aa-401f-bd96-45619a55120d': '1Password',
+  'd548826e-79b4-db40-a3d8-11116f7e8349': 'Bitwarden',
+  '531126d6-e717-415c-9320-3d9aa6981a6f': 'Dashlane',
+  'b84e4048-15dc-4dd0-8640-f4f60813c8af': 'NordPass',
+  '0ea242b4-43c4-4a1b-8b17-dd6d0b6baec6': 'Keeper',
+  '53414d53-554e-4700-0000-000000000000': 'Samsung Pass',
+};
+
+export function providerNameForAaguid(aaguid: string | null): string | null {
+  if (!aaguid) return null;
+  return KNOWN_AAGUIDS[aaguid] ?? null;
+}
