+/* My Account: passkey sign-in, registration and management */
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+[hidden] {
+  display: none !important;
+}
+
+/* ---------- Drawer dialog ---------- */
+
+.account-dialog {
+  margin: 0 0 0 auto;
+  height: 100dvh;
+  max-height: 100dvh;
+  width: min(460px, 100vw);
+  max-width: 100vw;
+  border: none;
+  padding: 0;
+  background: var(--light);
+  color: var(--text);
+  box-shadow: -8px 0 30px rgba(0, 0, 0, 0.25);
+}
+
+.account-dialog::backdrop,
+.small-dialog::backdrop {
+  background: rgba(30, 20, 15, 0.55);
+}
+
+.account-dialog[open] {
+  animation: slide-in 0.25s ease-out;
+}
+
+@keyframes slide-in {
+  from { transform: translateX(100%); }
+  to { transform: translateX(0); }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .account-dialog[open] { animation: none; }
+}
+
+.account-panel {
+  display: flex;
+  flex-direction: column;
+  min-height: 100%;
+}
+
+.account-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  padding: 1rem 1.25rem;
+  background: var(--primary);
+  color: white;
+  position: sticky;
+  top: 0;
+  z-index: 1;
+}
+
+.account-header h2 {
+  font-size: 1.2rem;
+  letter-spacing: 0.5px;
+}
+
+.icon-btn {
+  background: none;
+  border: none;
+  color: inherit;
+  font-size: 1.8rem;
+  line-height: 1;
+  cursor: pointer;
+  padding: 0 0.25rem;
+  border-radius: 4px;
+}
+
+.account-body {
+  padding: 1.25rem;
+  flex: 1;
+}
+
+.account-loading {
+  color: #6d4c41;
+}
+
