+/**
+ * "My Account" UI: passkey registration, sign-in (including autofill /
+ * conditional mediation), saved passkey management, profile updates and
+ * reauthentication for sensitive changes.
+ */
+
+import * as server from './passkey-server.js';
+import { creationOptionsFromJSON, requestOptionsFromJSON, credentialToJSON } from './webauthn.js';
+
+const SESSION_KEY = 'dailyGrind.session';
+const $ = (sel, root = document) => root.querySelector(sel);
+
+/* ------------------------------------------------------------------------ */
+/* API transport                                                             */
+/* ------------------------------------------------------------------------ */
+
+class ApiError extends Error {
+  constructor(status, data) {
+    super(data?.message || 'Request failed');
+    this.status = status;
+    this.code = data?.error || 'unknown_error';
+    this.data = data || {};
+  }
+}
+
+class ReauthCancelled extends Error {
+  constructor() {
+    super('Reauthentication cancelled');
+    this.name = 'ReauthCancelled';
+  }
+}
+
+/**
+ * JSON request to the account API. The session token stands in for an
+ * HttpOnly cookie; with a real backend this becomes a fetch() call with
+ * credentials: 'same-origin'.
+ */
+async function api(method, path, body) {
+  const res = await server.handle({
+    method,
+    path,
+    body: body === undefined ? undefined : JSON.stringify(body),
+    sessionToken: localStorage.getItem(SESSION_KEY),
+  });
+  if (res.setSession !== undefined) {
+    if (res.setSession) localStorage.setItem(SESSION_KEY, res.setSession);
+    else localStorage.removeItem(SESSION_KEY);
+  }
+  const data = res.body ? JSON.parse(res.body) : null;
+  if (res.status >= 400) throw new ApiError(res.status, data);
+  return data;
+}
+
+/* ------------------------------------------------------------------------ */
+/* State & feature detection                                                 */
+/* ------------------------------------------------------------------------ */
+
+const state = {
+  loaded: false,
+  user: null,
+  passkeys: [],
+  currentCredentialId: null,
+  verifiedAt: 0,
+  reauthWindowMs: server.REAUTH_WINDOW_MS,
+  rpId: location.hostname,
+  tab: 'signin',
+};
+
+const webauthnSupported =
+  window.isSecureContext &&
+  typeof window.PublicKeyCredential === 'function' &&
+  typeof navigator.credentials?.create === 'function' &&
+  typeof navigator.credentials?.get === 'function';
+
+async function conditionalMediationAvailable() {
+  try {
+    return webauthnSupported && (await PublicKeyCredential.isConditionalMediationAvailable?.()) === true;
+  } catch {
+    return false;
+  }
+}
+
+/** WebAuthn Signal API: keep passkey providers in sync with our records. */
+const signal = {
+  call(name, args) {
+    try {
+      const fn = window.PublicKeyCredential?.[name];
+      if (typeof fn === 'function') Promise.resolve(fn.call(PublicKeyCredential, args)).catch(() => {});
+    } catch {
+      /* best effort */
+    }
+  },
+  unknownCredential(credentialId) {
+    if (credentialId) this.call('signalUnknownCredential', { rpId: state.rpId, credentialId });
+  },
+  syncAccount() {
+    if (!state.user) return;
+    this.call('signalAllAcceptedCredentials', {
+      rpId: state.rpId,
+      userId: state.user.id,
+      allAcceptedCredentialIds: state.passkeys.map((p) => p.id),
+    });
+    this.call('signalCurrentUserDetails', {
+      rpId: state.rpId,
+      userId: state.user.id,
+      name: state.user.email,
+      displayName: state.user.displayName,
+    });
