+/* ------------------------------------------------------------------------ */
+/* Reauthentication                                                          */
+/* ------------------------------------------------------------------------ */
+
+let reauthInFlight = null;
+
+/**
+ * Ask the customer to verify with one of their passkeys (user verification
+ * required). Resolves once the server has refreshed the session's
+ * verification time; rejects with ReauthCancelled if dismissed.
+ */
+function reauthenticate({ continueLabel, description } = {}) {
+  if (reauthInFlight) return reauthInFlight;
