+  reauthInFlight = new Promise((resolve, reject) => {
+    const dialog = el.reauthDialog;
+    const btn = el.reauthConfirmBtn;
+    let settled = false;
+    let verified = false;
+
+    el.reauthTitle.textContent = 'Confirm it’s you';
+    el.reauthDesc.textContent = description || 'For your security, please verify with your passkey before making this change.';
+    el.reauthError.hidden = true;
+    btn.textContent = 'Verify with passkey';
+    btn.disabled = false;
+
+    const finish = (ok, err) => {
+      if (settled) return;
+      settled = true;
+      btn.removeEventListener('click', onClick);
+      dialog.removeEventListener('close', onClose);
+      if (dialog.open) dialog.close();
+      ok ? resolve() : reject(err || new ReauthCancelled());
+    };
