+    const onClose = () => finish(false);
+
+    const onClick = async () => {
+      if (verified) {
+        finish(true); // fresh user activation for the follow-up ceremony
+        return;
+      }
+      btn.disabled = true;
+      btn.setAttribute('aria-busy', 'true');
+      el.reauthError.hidden = true;
+      try {
+        const options = await api('POST', '/api/passkeys/reauth/options');
+        const credential = await navigator.credentials.get({ publicKey: requestOptionsFromJSON(options) });
+        const json = credentialToJSON(credential);
