+              {reauthError}
+            </div>
+          )}
+          {supported && passkeys.length > 0 && (
+            <button type="button" onClick={handleReauthPasskey} disabled={reauthBusy} className={`${primaryBtn} w-full`}>
+              <FingerPrintIcon className="h-5 w-5" aria-hidden="true" />
