+      const emptyMsg = document.getElementById('drink-empty');
+      const restoreBtn = document.getElementById('restore-drinks');
+      const resetBtn = document.getElementById('reset-drinks');
+      const status = document.getElementById('drink-status');
+      const cards = new Map();
+
+      const announce = (msg) => { status.textContent = ''; requestAnimationFrame(() => { status.textContent = msg; }); };
