+
+      function optionGroup(id, type, legend, options, inputType) {
+        return `<fieldset class="opt-group"><legend>${legend}</legend><div class="opts">${options.map((o) => `
+          <label class="opt"><input type="${inputType}" name="${type}-${id}" value="${o.key}" data-opt="${type}"><span>${esc(o.label)}</span></label>`).join('')}
+        </div></fieldset>`;
+      }
+
+      function createCard(id) {
+        const d = DRINKS[id];
+        const el = document.createElement('article');
+        el.className = 'card drink-card';
+        el.dataset.id = id;
+        el.setAttribute('role', 'listitem');
+        el.setAttribute('aria-labelledby', `drink-${id}-name`);
+        el.style.viewTransitionName = `drink-card-${id}`;
+        el.innerHTML = `
+          <div class="drink-media">
+            <img src="${d.img}" alt="${esc(d.alt)}" loading="lazy" width="600" height="300" onerror="this.remove()">
+            <span class="drink-price" data-vt style="--vt: drink-price-${id}" aria-label="Price"></span>
+            <div class="card-tools">
+              <button type="button" class="icon-btn" data-action="move" data-dir="-1" aria-label="Move ${esc(d.name)} earlier">&#8592;</button>
+              <button type="button" class="icon-btn" data-action="move" data-dir="1" aria-label="Move ${esc(d.name)} later">&#8594;</button>
+              <button type="button" class="icon-btn remove" data-action="remove" aria-label="Remove ${esc(d.name)}">&#10005;</button>
+            </div>
+          </div>
+          <h3 id="drink-${id}-name">${esc(d.name)}</h3>
+          <p class="desc">${esc(d.desc)}</p>
+          ${optionGroup(id, 'size', 'Size', SIZES, 'radio')}
+          ${optionGroup(id, 'milk', 'Milk', MILKS, 'radio')}
+          ${optionGroup(id, 'extra', 'Extras', EXTRAS, 'checkbox')}
+          <p class="your-cup" id="drink-${id}-cup">Your cup</p>
+          <ul class="mod-list" aria-labelledby="drink-${id}-cup"></ul>
+          <a href="${d.href}" class="btn">View Details</a>`;
+        cards.set(id, el);
+        syncCard(id, 'none');
+        return el;
+      }
+
+      function modsFor(id) {
+        const c = state.custom[id];
+        const size = byKey(SIZES, c.size);
+        const mods = [{ key: 'size', label: size.label, base: true }];
+        if (c.milk !== DRINKS[id].milk) mods.push({ key: 'milk', label: byKey(MILKS, c.milk).key === 'none' ? 'No milk' : `${byKey(MILKS, c.milk).label} milk` });
+        for (const k of c.extras) mods.push({ key: `extra-${k}`, label: byKey(EXTRAS, k).label });
+        return mods;
+      }
+
+      function priceFor(id) {
+        const c = state.custom[id];
+        return DRINKS[id].base + byKey(SIZES, c.size).delta + byKey(MILKS, c.milk).delta +
+          c.extras.reduce((sum, k) => sum + byKey(EXTRAS, k).delta, 0);
+      }
+
+      // Bring a card's controls, price and "Your cup" chips in line with state.
+      function syncCard(id, mode) {
+        const el = cards.get(id);
+        const c = state.custom[id];
+        el.querySelector('.drink-price').textContent = money.format(priceFor(id));
+        el.querySelectorAll('input[data-opt]').forEach((input) => {
+          const t = input.dataset.opt;
+          input.checked = t === 'extra' ? c.extras.includes(input.value) : c[t] === input.value;
+        });
+
+        const list = el.querySelector('.mod-list');
+        const mods = modsFor(id);
+        const existing = new Map(liveItems(list, ':scope > .mod-chip').map((li) => [li.dataset.key, li]));
+        const wanted = new Set(mods.map((m) => m.key));
+        existing.forEach((li, key) => { if (!wanted.has(key)) removeNode(li, mode); });
+
+        let cursor = null;
+        for (const m of mods) {
+          let li = existing.get(m.key);
+          if (!li) {
+            li = document.createElement('li');
+            li.className = 'mod-chip';
+            li.dataset.key = m.key;
+            li.dataset.vt = '';
+            li.dataset.flip = '';
+            li.style.setProperty('--vt', `drink-mod-${id}-${m.key}`);
+          }
+          li.classList.toggle('is-base', !!m.base);
+          li.innerHTML = `<span>${esc(m.label)}</span>${m.base ? '' : `<button type="button" data-action="drop-mod" data-key="${m.key}" aria-label="Remove ${esc(m.label)}">&#10005;</button>`}`;
+          const ref = cursor ? cursor.nextElementSibling : list.firstElementChild;
+          if (li !== ref) list.insertBefore(li, ref);
+          cursor = li;
+        }
+      }
+
+      function syncGrid(mode) {
+        const live = liveItems(grid, ':scope > .drink-card');
+        live.forEach((el) => {
+          if (state.order.includes(el.dataset.id)) return;
+          cards.delete(el.dataset.id); // a restored drink gets a fresh element
+          removeNode(el, mode);
+        });
+
+        const current = liveItems(grid, ':scope > .drink-card').map((el) => el.dataset.id);
+        if (current.join() !== state.order.join()) {
+          for (const id of state.order) grid.appendChild(cards.get(id) || createCard(id));
+        }
+        state.order.forEach((id, i) => {
+          const el = cards.get(id);
+          el.querySelector('[data-dir="-1"]').disabled = i === 0;
+          el.querySelector('[data-dir="1"]').disabled = i === state.order.length - 1;
+        });
+
+        const removed = DEFAULT_ORDER.length - state.order.length;
