+  'use strict';
+
+  // ---------------------------------------------------------------------------
+  // Card content (HTML strings). In production this could come from a CMS or
+  // API, so it is treated as untrusted and always sanitized before insertion.
+  // ---------------------------------------------------------------------------
+  var SEASONAL_FAVORITES = [
+    '<div class="card">' +
+      '<img src="https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=600&q=80" alt="Latte with latte art in a ceramic cup" loading="lazy" width="600" height="400">' +
+      '<h3>Maple Oat Latte</h3>' +
+      '<p>Creamy oat milk with a hint of Vermont maple syrup.</p>' +
+      '<a href="/menu/seasonal" class="btn">View Details</a>' +
+    '</div>',
+    '<div class="card">' +
+      '<img src="https://images.unsplash.com/photo-1510707577719-ae7c14805e3a?auto=format&fit=crop&w=600&q=80" alt="Freshly pulled espresso shot" loading="lazy" width="600" height="400">' +
+      '<h3>Dark Roast Espresso</h3>' +
+      '<p>Bold, smokey, and perfect for a morning boost.</p>' +
+      '<a href="/menu/espresso" class="btn">View Details</a>' +
+    '</div>',
+    '<div class="card">' +
+      '<img src="https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=600&q=80" alt="Iced cold brew coffee in a glass" loading="lazy" width="600" height="400">' +
+      '<h3>Cold Brew</h3>' +
+      '<p>Steeped for 18 hours for maximum smoothness.</p>' +
+      '<a href="/menu/cold-brew" class="btn">View Details</a>' +
+    '</div>'
+  ];
+
+  // ---------------------------------------------------------------------------
+  // Sanitizer configuration: a strict allowlist sized to what a card needs.
+  // ---------------------------------------------------------------------------
+  // Only same-origin relative paths ("/menu/...") or https: URLs are allowed.
+  // Protocol-relative ("//evil.example") and every other scheme
+  // (javascript:, data:, vbscript:, http:, ...) are rejected.
+  var SAFE_URL = /^(?:\/(?!\/)|https:\/\/)/i;
+
+  var PURIFY_CONFIG = {
+    ALLOWED_TAGS: ['div', 'h3', 'p', 'a', 'img', 'span', 'strong', 'em', 'br'],
+    ALLOWED_ATTR: ['class', 'href', 'src', 'alt', 'title', 'loading', 'width', 'height'],
+    ALLOWED_URI_REGEXP: SAFE_URL,
+    ALLOW_DATA_ATTR: false,
+    ALLOW_ARIA_ATTR: false,
+    ALLOW_UNKNOWN_PROTOCOLS: false,
+    SAFE_FOR_TEMPLATES: true,
+    SANITIZE_DOM: true,       // block DOM clobbering via id/name
+    SANITIZE_NAMED_PROPS: true,
+    WHOLE_DOCUMENT: false,
+    RETURN_DOM: false,
+    RETURN_DOM_FRAGMENT: false
+  };
+
+  var hooksInstalled = false;
+
+  function installHooks(purify) {
+    if (hooksInstalled) return;
+    hooksInstalled = true;
+
+    purify.addHook('afterSanitizeAttributes', function (node) {
