+      }
+    });
+  }
+
+  function getPurify() {
+    var purify = window.DOMPurify;
+    if (!purify || typeof purify.sanitize !== 'function' || !purify.isSupported) {
+      return null;
+    }
+    installHooks(purify);
+    return purify;
+  }
