+    // (e.g. a future `el.innerHTML = str`) and sanitizes it, while refusing
+    // to mint script or script-URL values from strings outright.
+    if (!tt.defaultPolicy) {
+      tt.createPolicy('default', {
+        createHTML: sanitize,
+        createScript: function () {
+          throw new TypeError('[Daily Grind] Blocked string-to-script conversion.');
+        },
+        createScriptURL: function () {
+          throw new TypeError('[Daily Grind] Blocked string-to-script-URL conversion.');
+        }
+      });
+    }
+  }
+
+  function toTrustedHTML(html) {
+    // Browsers with Trusted Types get a TrustedHTML object; others get a
+    // DOMPurify-sanitized string. Either way, the markup has been sanitized.
+    return htmlPolicy ? htmlPolicy.createHTML(html) : sanitize(html);
+  }
+
+  /**
+   * Safely replace the contents of `container` with sanitized markup.
+   * Prefers the native HTML Sanitizer API (Element.setHTML) on top of the
+   * DOMPurify-sanitized output for defense in depth when available.
+   */
+  function setSafeHTML(container, html) {
+    var trusted = toTrustedHTML(html);
+    if (typeof container.setHTML === 'function') {
+      // setHTML always applies the browser's built-in XSS-safe sanitizer.
+      container.setHTML(trusted.toString());
+    } else {
+      container.innerHTML = trusted;
+    }
+  }
+
+  // ---------------------------------------------------------------------------
+  // Render.
+  // ---------------------------------------------------------------------------
+  function renderSeasonalFavorites() {
+    var grid = document.getElementById('seasonal-favorites');
+    if (!grid) return;
+
+    try {
+      setSafeHTML(grid, SEASONAL_FAVORITES.join(''));
+      grid.removeAttribute('aria-busy');
+    } catch (err) {
+      console.error(err);
+      grid.removeAttribute('aria-busy');
+      var msg = document.createElement('p');
+      msg.className = 'grid-fallback';
+      msg.textContent = 'Our seasonal menu is brewing. Please check back shortly or visit the full menu.';
+      grid.replaceChildren(msg);
+    }
+  }
+
+  // Expose a minimal, safe API for other scripts on the page.
+  window.DailyGrind = Object.freeze({
+    setSafeHTML: setSafeHTML,
+    renderSeasonalFavorites: renderSeasonalFavorites
+  });
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', renderSeasonalFavorites);
+  } else {
+    renderSeasonalFavorites();
+  }
+})();
